In this work we study the Kakinuma model obtained when the approximate velocity potentials
are defined by
\begin{equation}\label{intro:appk}
	\begin{cases}
		\displaystyle
		\Phi_1^\mathrm{app}(\bm{x},z,t) := \sum_{i=0}^N (-z+h_1)^{2i}\phi_{1,i}(\bm{x},t), \\[2.5ex]
		\displaystyle
		\Phi_2^\mathrm{app}(\bm{x},z,t) := \sum_{i=0}^{N^*} (z+h_2-b(\bm{x}))^{p_i}\phi_{2,i}(\bm{x},t),
	\end{cases}
\end{equation}

where $N, N^*$, and $p_0,p_1,\ldots,p_{N^*}$ are nonnegative integers satisfying ${0=p_0<p_1<\cdots<p_{N^*}}$.

Moreover, T.~Iguchi~\cite{Iguchi2018-1,Iguchi2018-2} showed that under the choice of the function system 

\begin{equation}\label{intro:base}
	Z_i(z;b(\bm{x})) = 
	\begin{cases}
		(z+h)^{2i} & \mbox{in the case of the flat bottom}, \\
		(z+h-b(\bm{x}))^i & \mbox{in the case of a variable bottom},
	\end{cases}
\end{equation}

the Isobe--Kakinuma model is a higher order shallow water approximation for the water wave problem 
in the strongly nonlinear regime.

\begin{equation}\label{intro:base}
	Z_i(z;b(\bm{x})) = 
	\begin{cases}
		(z+h)^{2i} & \mbox{in the case of the flat bottom}, \\
		(z+h-b(\bm{x}))^i & \mbox{in the case of a variable bottom},
	\end{cases}
\end{equation}

\label{P.compatibility}
	Initial data satisfying the compatibility conditions and necessary bounds in Theorem~\ref{T.uniform} are uniquely 
	determined (up to an additive constant) by sufficiently regular initial data for the canonical variables of the Hamiltonian structure.

In the last result we assume the existence of a solution to the full model with a uniform bound since 
for general initial data in Sobolev spaces, one cannot expect to construct a solution to the initial value problem,
due to the ill-posedness of the problem discussed previously.

\begin{equation}\label{intro:Kakinuma-compact} 
	\begin{cases}
		\displaystyle
		{\bm l}_1(H_1)\partial_t\zeta + L_1(H_1){\bm \phi}_1 = {\bm 0}, \\
		\displaystyle
		{\bm l}_2(H_2)\partial_t\zeta - L_2(H_2,b){\bm \phi}_2 = {\bm 0}, \\
		{\rho}_1\bigl\{ {\bm l}_1(H_1) \cdot \partial_t{\bm \phi}_1 
		+ \frac12\bigl( |{\bm u}_1|^2 +  w_1^2 \bigr) \bigr\} \\
		\quad
		- {\rho}_2\bigl\{ {\bm l}_2(H_2) \cdot \partial_t{\bm \phi}_2 
		+ \frac12\bigl( |{\bm u}_2|^2 + w_2^2 \bigr) \bigr\} 
		+ (\rho_1-\rho_2)g\zeta = 0,
	\end{cases}
\end{equation}

To this end, we write the linearized system under the form

\begin{equation}\label{intro:linearized}
	\mathscr{A}_1(\partial_t+\bm{u}\cdot\nabla)\dot{\bm{U}} + \mathscr{A}_0^\mathrm{mod}\dot{\bm{U}} = \dot{\bm{F}},
\end{equation}

where $\dot{\bm{U}}:=(\dot{\zeta}, \dot{\bm{\phi}}_1, \dot{\bm{\phi}}_2)^\mathrm{T}$ is the deviation from the reference state $\bm{U}:=({\zeta}, {\bm{\phi}}_1, {\bm{\phi}}_2)^\mathrm{T}$, $\bm{u}$ is a suitable velocity which is a convex combination of  $\bm{u}_1$ and $\bm{u}_2$ whose weights depend on $\rho_\ell$, $H_\ell$ as well as $\alpha_\ell$ ($\ell=1,2$) the positive constants mentioned previously,  $\dot{\bm{F}}$ represent lower order terms and 
 $\mathscr{A}_1:=\mathscr{A}_1(\bm{U})$ is a skew-symmetric matrix and $\mathscr{A}_0^\mathrm{mod}:=\mathscr{A}_0^\mathrm{mod}(\bm{U})$ is a linear operator symmetric in $L^2$.

It follows from the second relation in~\eqref{parameters} that 

\begin{equation}\label{parameter-relation}
1 < \min\biggl\{ \frac{\underline{h}_1}{\underline{\rho}_1}, \frac{\underline{h}_2}{\underline{\rho}_2} \biggr\} \leq 2.
\end{equation}

Specifically, $\mathscr{E}$ is the sum of the kinetic energies of the fluids in the upper 
and the lower layers and the potential energy due to the gravity defined as

\begin{align*}
\mathscr{E}
&:= \sum_{\ell=1,2}\iint_{\Omega_\ell(t)}\frac12\underline{\rho}_\ell
 \bigl( |\nabla\Phi_\ell(\bm{x},z,t)|^2 + \delta^{-2}(\partial_z\Phi_\ell(\bm{x},z,t))^2 \bigr) \mathrm{d}\bm{x}\mathrm{d}z 
 + \int_{\mathbf{R}^n}\frac12\zeta(\bm{x},t)^2\mathrm{d}\bm{x} \\
&= \sum_{\ell=1,2}\frac12\underline{\rho}_\ell(\Lambda_\ell(\zeta)\phi_\ell(t),\phi_\ell(t))_{L^2}
 + \frac12\|\zeta(t)\|_{L^2}^2.
\end{align*}

The canonical variables are the elevation of the interface $\zeta$ and $\phi$ defined by 

\begin{align}\label{canonical-variable}
\phi(\bm{x},t) 
&:= \underline{\rho}_2\Phi_2^\mathrm{app}(\bm{x},\zeta(\bm{x},t),t)
  - \underline{\rho}_1\Phi_1^\mathrm{app}(\bm{x},\zeta(\bm{x},t),t) \\
&= \underline{\rho}_2\sum_{i=0}^{N^*} H_2(\bm{x},t)^{p_i}\phi_{2,i}(\bm{x},t)
  - \underline{\rho}_1\sum_{i=0}^N H_1(\bm{x},t)^{2i}\phi_{1,i}(\bm{x},t),
  \nonumber
\end{align}

where $\Phi_\ell^\mathrm{app}$ $(\ell=1,2)$ are nondimensional versions of the approximate velocity potentials, 
which are defined by 

\begin{equation}\label{Approximation-nondim} 
\begin{cases}
 \displaystyle
  \Phi_1^\mathrm{app}(\bm{x},z,t) := \sum_{i=0}^N (1-\underline{h}_1^{-1}z)^{2i}\phi_{1,i}(\bm{x},t), \\[2.5ex]
 \displaystyle
  \Phi_2^\mathrm{app}(\bm{x},z,t) := \sum_{i=0}^{N^*} (1+\underline{h}_2^{-1}(z-b(\bm{x})))^{p_i}\phi_{2,i}(\bm{x},t),
\end{cases}
\end{equation}

and $H_\ell$ $(\ell=1,2)$ are depths of the upper and lower layers defined by~\eqref{thicknesses}.

\begin{equation}\label{def-uw}
 \left\{\begin{array}{ll}
 \displaystyle {\bm u}_1 := ({\bm l}_1(H_1) \otimes \nabla)^\mathrm{T}{\bm \phi}_{1}, \qquad
  & \displaystyle w_1 := - {\bm l}_1^\prime(H_1) \cdot {\bm\phi}_{1}, \\
 \displaystyle {\bm u}_2 := ({\bm l}_2(H_2) \otimes \nabla)^\mathrm{T}{\bm\phi}_{2}
  - ( {\bm l}_2^\prime(H_2) \cdot {\bm\phi}_{2})\underline{h}_2^{-1}\nabla b, \qquad 
  & \displaystyle w_2 := {\bm l}_2^\prime(H_2) \cdot {\bm\phi}_{2}.
 \end{array}
 \right.
\end{equation}

\begin{equation}\label{Kakinuma-dimensionless-compact} 
\begin{cases}
 \displaystyle
 {\bm l}_1(H_1)\partial_t\zeta + \underline{h}_1 L_1(H_1,\delta,\underline{h}_1){\bm \phi}_1 = {\bm 0}, \\
 \displaystyle
 {\bm l}_2(H_2)\partial_t\zeta - \underline{h}_2 L_2(H_2,b,\delta,\underline{h}_2){\bm \phi}_2 = {\bm 0}, \\
 \underline{\rho}_1\bigl\{ {\bm l}_1(H_1) \cdot \partial_t{\bm \phi}_1 
   + \frac12\bigl( |{\bm u}_1|^2 + (\underline{h}_1\delta)^{-2} w_1^2 \bigr) \bigr\} \\
 \quad
 - \underline{\rho}_2\bigl\{ {\bm l}_2(H_2) \cdot \partial_t{\bm \phi}_2 
  + \frac12\bigl( |{\bm u}_2|^2 +  (\underline{h}_2\delta)^{-2} w_2^2 \bigr) \bigr\} 
 - \zeta = 0. 
\end{cases}
\end{equation}

\label{theorem-uniform}
Let $c_0, M_0, \underline{h}_\mathrm{min}$ be positive constants and $m$ an integer such that ${m>\frac{n}{2}+1}$. 
There exist a time $T>0$ and a constant $M>0$ such that for any positive parameters 
$\underline{\rho}_1, \underline{\rho}_2, \underline{h}_1, \underline{h}_2, \delta$ satisfying the natural 
restrictions~\eqref{parameters}, $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, as well as the condition 
${\underline{h}_\mathrm{min} \leq \underline{h}_1, \underline{h}_2}$, 
if the initial data $(\zeta_{(0)},\bm{\phi}_{1(0)},\bm{\phi}_{2(0)})$ 
and the bottom topography $b$ satisfy 

\begin{equation}\label{uniform-ini}
\begin{cases}
\displaystyle
\|\zeta_{(0)}\|_{H^m}^2 + \sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell\bigl(
 \|\nabla\bm{\phi}_{\ell(0)}\|_{H^m}^2 + (\underline{h}_\ell\delta)^{-2}\|\bm{\phi}_{\ell(0)}'\|_{H^m}^2\bigr) \leq M_0, \\
\underline{h}_2^{-1}\bigl(\|b\|_{W^{m+1,\infty}} + (\underline{h}_2\delta)\|b\|_{W^{m+2,\infty}} \bigr) \leq M_0,
\end{cases}
\end{equation}

the non-cavitation assumption 

\begin{equation}\label{NonCavitation}
H_{1(0)}(\bm{x}) \geq c_0, \quad H_{2(0)}(\bm{x}) \geq c_0 \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{equation}

the stability condition

\begin{equation}\label{Stability}
 a_{(0)}(\bm{x})- \frac{\underline{\rho}_1\underline{\rho}_2}{
  \underline{\rho}_1\underline{h}_2H_{2(0)}(\bm{x})\alpha_2 + \underline{\rho}_2\underline{h}_1H_{1(0)}(\bm{x})\alpha_1}
  |{\bm u}_{1(0)}(\bm{x})-{\bm u}_{2(0)}(\bm{x})|^2 \geq c_0 \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{equation}

with positive constants $\alpha_1$ and $\alpha_2$ defined by~\eqref{def-alpha-intro}, and the compatibility conditions 

\begin{equation}\label{Compatibility}
\begin{cases}
 \mathcal{L}_{1,i}(H_{1(0)},\delta,\underline{h}_1) {\bm \phi}_{1(0)} = 0 \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \mathcal{L}_{2,i}(H_{2(0)},b,\delta,\underline{h}_2) {\bm \phi}_{2(0)} = 0 \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\
 \underline{h}_1\mathcal{L}_{1,0}(H_{1(0)},\delta,\underline{h}_1)  {\bm \phi}_{1(0)}
  +  \underline{h}_2\mathcal{L}_{2,0}(H_{2(0)},b,\delta,\underline{h}_2)  {\bm \phi}_{2(0)} = 0,
\end{cases}
\end{equation}

then the initial value problem~\eqref{Kakinuma-dimensionless}--\eqref{Kaki:IC} has a unique solution 
$(\zeta,\bm{\phi}_1,\bm{\phi}_2)$ on the time interval $[0,T]$ satisfying 

\[
\begin{cases}
\zeta,\nabla\phi_{1,0},\nabla\phi_{2,0} \in C([0,T];H^m)\cap  C^1([0,T];H^{m-1}), \\
{\bm \phi}_1^{\prime},{\bm \phi}_2^{\prime} \in C([0,T];H^{m+1})\cap  C^1([0,T];H^{m}),
\end{cases}
\]

where we recall the notation 
${\bm \phi}_1^{\prime} = (\phi_{1,1},\phi_{1,2},\ldots,\phi_{1,N})^\mathrm{T}$ and 
${\bm \phi}_2^{\prime} = (\phi_{2,1},\phi_{2,2},\ldots,\phi_{2,N^*})^\mathrm{T}$. 
Moreover, the solution satisfies the uniform bound 

\begin{equation}\label{uniform-sol}
\|\zeta(t)\|_{H^m}^2 + \sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell\bigl(
 \|\nabla\bm{\phi}_\ell(t)\|_{H^m}^2 + (\underline{h}_\ell\delta)^{-2}\|\bm{\phi}_\ell'(t)\|_{H^m}^2\bigr) \leq M
\end{equation}

for $t\in[0,T]$ together with 

\begin{equation}\label{uniform-below}
\begin{cases}
\displaystyle
 a(\bm{x},t)- \frac{\underline{\rho}_1\underline{\rho}_2}{
  \underline{\rho}_1\underline{h}_2H_2(\bm{x},t)\alpha_2 + \underline{\rho}_2\underline{h}_1H_1(\bm{x},t)\alpha_1}
  |{\bm u}_1(\bm{x},t)-{\bm u}_2(\bm{x},t)|^2 \geq c_0/2, \\
\displaystyle
 H_1(\bm{x},t) \geq c_0/2, \quad H_2(\bm{x},t) \geq c_0/2
 \qquad \mbox{for}\quad \bm{x}\in\mathbf{R}^n, t\in[0,T].
\end{cases}
\end{equation}

\begin{equation}\label{uniform-below}
\begin{cases}
\displaystyle
 a(\bm{x},t)- \frac{\underline{\rho}_1\underline{\rho}_2}{
  \underline{\rho}_1\underline{h}_2H_2(\bm{x},t)\alpha_2 + \underline{\rho}_2\underline{h}_1H_1(\bm{x},t)\alpha_1}
  |{\bm u}_1(\bm{x},t)-{\bm u}_2(\bm{x},t)|^2 \geq c_0/2, \\
\displaystyle
 H_1(\bm{x},t) \geq c_0/2, \quad H_2(\bm{x},t) \geq c_0/2
 \qquad \mbox{for}\quad \bm{x}\in\mathbf{R}^n, t\in[0,T].
\end{cases}
\end{equation}

\label{remark-alpha}
The constants $\alpha_1$ and $\alpha_2$ are defined by
\begin{equation}\label{def-alpha-intro}
	\alpha_\ell := \frac{\det A_{\ell,0}}{\det \tilde{A}_{\ell,0}}, \qquad
	\tilde{A}_{\ell,0} := 
	\begin{pmatrix}
		0 & \bm{1}^\mathrm{T} \\
		-\bm{1} & A_{\ell,0}
	\end{pmatrix},
\end{equation}

for $\ell=1,2$, where $\bm{1}:=(1,\ldots,1)^\mathrm{T}$ and the matrices $A_{1,0}$ and $A_{2,0}$ are defined by
\[
	\begin{cases}
		\displaystyle
		A_{1,0} := \left( \frac{1}{2(i+j)+1} \right)_{0\leq i,j\leq N}, \\
		\displaystyle
		A_{2,0} := \left( \frac{1}{p_i+p_j+1}\right)_{0\leq i,j\leq N^*}.
	\end{cases}
\]

Hence, $\alpha_1$ and $\alpha_2$ are positive constants depending only on $N$ and the nonnegative integers $0=p_0<p_1<\ldots<p_{N^*}$, respectively, 
and go to $0$ as $N,N^*\to\infty$.

\label{theorem-consistency1}
Let $c, M$ be positive constants and $m$ an integer such that $m \geq 4(N+1)$ and $m>\frac{n}{2}+1$. 
We assume {\rm (H1)} or {\rm (H2)}. 
There exists a positive constant $C$ such that for any positive parameters $\underline{\rho}_1, \underline{\rho}_2, \underline{h}_1, \underline{h}_2, \delta$ satisfying 
$\underline{h}_1\delta, \underline{h}_2\delta \leq 1$ and for any solution $(\zeta,\bm{\phi}_1,\bm{\phi}_2)$ to the Kakinuma model~\eqref{Kakinuma-dimensionless} 
on a time interval $[0,T]$ with a bottom topography $b\in W^{m+1,\infty}$ satisfying 

\begin{equation}\label{cond.consisitency}
\begin{cases}
 \underline{h}_1^{-1}\|\zeta(t)\|_{H^m} + \underline{h}_2^{-1}\|\zeta(t)\|_{H^m}
  + \underline{h}_2^{-1}\|b\|_{W^{m+1,\infty}} \leq M, \\
 H_1(\bm{x},t)\geq c, \quad H_2(\bm{x},t)\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n, t\in[0,T],
\end{cases}
\end{equation}

if we define $\phi_\ell:=\bm{l}_\ell(H_\ell)\cdot\bm{\phi}_\ell$ for $\ell=1,2$, then $(\zeta,\phi_1,\phi_2)$ 
satisfy approximately the full model for interfacial gravity waves as 

\[
\begin{cases}
\partial_t\zeta + \Lambda_1(\zeta,\delta,\underline{h}_1)\phi_1=\mathfrak{r}_1,\\
\partial_t\zeta - \Lambda_2(\zeta,b,\delta,\underline{h}_2)\phi_2 =\mathfrak{r}_2,\\
\displaystyle
\underline{\rho}_1\biggl( \partial_t\phi_1 + \frac12|\nabla\phi_1|^2
 - \frac12\delta^2 \frac{(\Lambda_1(\zeta,\delta,\underline{h}_1)\phi_1
  - \nabla\zeta \cdot \nabla\phi_1 )^2}{1+\delta^2|\nabla\zeta|^2} \biggr) \\
\displaystyle\quad
 - \underline{\rho}_2\biggl( \partial_t\phi_2 + \frac12|\nabla\phi_2|^2
  - \frac12\delta^2 \frac{(\Lambda_2(\zeta,b,\delta,\underline{h}_2)\phi_2
   + \nabla\zeta \cdot \nabla\phi_2 )^2}{1+\delta^2|\nabla\zeta|^2} \biggr)
 - \zeta = \mathfrak{r}_0.
\end{cases}
\]

Here, the errors $(\mathfrak{r}_1,\mathfrak{r}_2,\mathfrak{r}_0)$ satisfy 

\[
\begin{cases}
 \|\mathfrak{r}_\ell(t)\|_{H^{m-4(N+1)}}
  \leq C\underline{h}_\ell(\underline{h}_\ell\delta)^{4N+2}\|\nabla\phi_\ell(t)\|_{H^{m-1}}
  \quad (\ell=1,2), \\
 \displaystyle
 \|\mathfrak{r}_0(t)\|_{H^{m-4(N+1)}} \leq 
  C\sum_{\ell=1,2}\underline{\rho}_\ell(\underline{h}_\ell\delta)^{4N+2}\|\nabla\phi_\ell(t)\|_{H^{m-1}}^2
\end{cases}
\]

for $t\in[0,T]$.

\begin{equation}\label{cond.consisitency}
\begin{cases}
 \underline{h}_1^{-1}\|\zeta(t)\|_{H^m} + \underline{h}_2^{-1}\|\zeta(t)\|_{H^m}
  + \underline{h}_2^{-1}\|b\|_{W^{m+1,\infty}} \leq M, \\
 H_1(\bm{x},t)\geq c, \quad H_2(\bm{x},t)\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n, t\in[0,T],
\end{cases}
\end{equation}

\label{theorem-consistency2}
Let $c, M$ be positive constants and $m$ an integer such that $m \geq 4(N+1)$ and $m>\frac{n}{2}+1$. 
We assume {\rm (H1)} or {\rm (H2)}. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{\rho}_1, \underline{\rho}_2, \underline{h}_1, \underline{h}_2, \delta$ 
satisfying $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$ and for any 
solution $(\zeta,\phi_1,\phi_2)$ to the full model for interfacial gravity waves~\eqref{full-model-evolution} 
on a time interval $[0,T]$ with a bottom topography $b\in W^{m+1,\infty}$ satisfying~\eqref{cond.consisitency}, 
if we define $H_1$ and $H_2$ as in~\eqref{thicknesses} and $\bm{\phi}_1$ and $\bm{\phi}_2$ as the unique solutions to the problems 

\begin{equation}\label{Conditions}
\begin{cases}
 \bm{l}_1(H_1)\cdot\bm{\phi}_1=\phi_1, \quad \mathcal{L}_{1,i}(H_1,\delta,\underline{h}_1)\bm{\phi}_1=0
  \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \bm{l}_2(H_2)\cdot\bm{\phi}_2=\phi_2, \quad \mathcal{L}_{2,i}(H_2,b,\delta,\underline{h}_2)\bm{\phi}_2=0
  \quad\mbox{for}\quad i=1,2,\ldots,N^*,
\end{cases}
\end{equation}

then $(\zeta,\bm{\phi}_1,\bm{\phi}_2)$ satisfy approximately the Kakinuma model as

\[
\begin{cases}
 \displaystyle
 {\bm l}_1(H_1)\underline{h}_1^{-1}
 \partial_t\zeta + L_1(H_1,\delta,\underline{h}_1){\bm \phi}_1
  = \tilde{\bm{\mathfrak{r}}}_1, \\
 \displaystyle
 {\bm l}_2(H_2)\underline{h}_2^{-1}
 \partial_t\zeta - L_2(H_2,b,\delta,\underline{h}_2){\bm \phi}_2
  = \tilde{\bm{\mathfrak{r}}}_2, \\
 \underline{\rho}_1\bigl\{ {\bm l}_1(H_1) \cdot \partial_t{\bm \phi}_1 
   + \frac12\bigl( |{\bm u}_1|^2 + (\underline{h}_1\delta)^{-2} w_1^2 \bigr) \bigr\} \\
 \quad
 - \underline{\rho}_2\bigl\{ {\bm l}_2(H_2) \cdot \partial_t{\bm \phi}_2 
  + \frac12\bigl( |{\bm u}_2|^2 +  (\underline{h}_2\delta)^{-2} w_2^2 \bigr) \bigr\} 
 - \zeta = \tilde{\mathfrak{r}}_0. 
\end{cases}
\]

Here, the errors $(\tilde{\bm{\mathfrak{r}}}_1,\tilde{\bm{\mathfrak{r}}}_2,\tilde{\mathfrak{r}}_0)$ satisfy 

\begin{equation}\label{error-estimate}
\begin{cases}
 \|\tilde{\bm{\mathfrak{r}}}_\ell(t)\|_{H^{m-4(N+1)}}
  \leq C (\underline{h}_\ell\delta)^{4N+2}\|\nabla\phi_\ell(t)\|_{H^{m-1}}
  \quad (\ell=1,2), \\
 \displaystyle
 \|\tilde{\mathfrak{r}}_0(t)\|_{H^{m-4(N+1)}} \leq 
  C\sum_{\ell=1,2}\underline{\rho}_\ell(\underline{h}_\ell\delta)^{4N+2}\|\nabla\phi_\ell(t)\|_{H^{m-1}}^2
\end{cases}
\end{equation}

for $t\in[0,T]$.

{\rm
The unique existence of the solutions $\bm{\phi}_1$ and $\bm{\phi}_2$ to the problems~\eqref{Conditions} 
is guaranteed by Lemma~\ref{L.Lambda} below under an additional assumption $\phi_1(\cdot,t),\phi_2(\cdot,t) 
\in \mathring{H}^m$. 
Lemma~\ref{L.Lambda} is essentially a simple corollary of~\cite[Lemma 3.4]{Iguchi2018-2}. 
}

\label{R.app-sol}
{\rm
In order to define the approximate solution $(\bm{\phi}_1,\bm{\phi}_2)$ to the Kakinuma model~\eqref{Kakinuma-dimensionless}
from the solution $(\zeta,\phi_1,\phi_2)$ to the full model, we can use, in place of~\eqref{Conditions}, 
the following system of equations 

\begin{equation}\label{Conditions-v2}
\begin{cases}
 \mathcal{L}_{1,i}(H_1,\delta,\underline{h}_1)\bm{\phi}_1=0 \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \mathcal{L}_{2,i}(H_1,b,\delta,\underline{h}_2)\bm{\phi}_2=0 \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\
 \underline{h}_1\mathcal{L}_{1,0}(H_1,\delta,\underline{h}_1) {\bm \phi}_1
  + \underline{h}_2\mathcal{L}_{2,0}(H_2,b,\delta,\underline{h}_2) {\bm \phi}_2  = 0, \\
 \underline{\rho}_2\bm{l}_2(H_2)\cdot\bm{\phi}_2-\underline{\rho}_1\bm{l}_1(H_1)\cdot\bm{\phi}_1 = \phi,
\end{cases}
\end{equation}

where $\phi=\underline{\rho}_2\phi_2-\underline{\rho}_1\phi_1$ is the canonical variable for the full model 
for interfacial gravity waves. 
The above system is nothing but the compatibility conditions~\eqref{necessary-delta} together with 
the definition~\eqref{canonical-variable2} of the canonical variable for the Kakinuma model. 
The existence of the approximate solution $(\bm{\phi}_1,\bm{\phi}_2)$ is guaranteed by 
Lemma~\ref{L.elliptic} given in Section~\ref{S.elliptic}. 
Then, we have similar error estimates to~\eqref{error-estimate}. 
For details, we refer to Proposition~\ref{prop-consistency}. 
}

define $L_{ij} = L_{ij}(H,b,\delta)$ $(i,j=0,1,\ldots,N^*)$ by 

\begin{align}\label{def-Lij}
L_{ij}\varphi_{j}
:=& - \nabla\cdot\biggl(
   \frac{1}{p_i+p_j+1}H^{p_i+p_j+1}\nabla\varphi_{j}
   - \frac{p_j}{p_i+p_j}H^{p_i+p_j}\varphi_{j}\nabla b\biggr) \\
 &- \frac{p_i}{p_i+p_j}H^{p_i+p_j}\nabla b\cdot\nabla\varphi_{j}
   + \frac{p_ip_j}{p_i+p_j-1}H^{p_i+p_j-1}(\delta^{-2}+ |\nabla b|^2)\varphi_{j}, \nonumber
\end{align}
where we use the notational convention $0/0 = 0$.

\label{L.L-invertible}
Let $c, M$ be positive constants and $m$ an integer such that $m>\frac{n}{2}+1$. 
There exists a positive constant $C$ such that if $\zeta\in H^m$, $b\in W^{m,\infty}$, and $H=1+\zeta-b$ satisfy 

\begin{equation}\label{eq-Hyp0}
\begin{cases}
 \|\zeta\|_{H^m}+\|b\|_{W^{m,\infty}}\leq M, \\
 H(\bm{x})\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\end{equation}

then for any $k=\pm 0,\dots, \pm(m-1)$, any $\delta\in(0,1]$, and any $\phi\in\mathring{H}^{k+1}$ 
there exists a unique solution $\bm{\phi}=(\phi_0,\phi_1,\ldots,\phi_{N^*})=(\phi_0,\bm{\phi}') 
\in \mathring{H}^{k+1}\times(H^{k+1})^{N^*}$ 
to the problem 

\begin{equation}\label{condition}
\begin{cases}
 \mathcal{L}_i(H,b,\delta){\bm \phi} = 0 \quad \mbox{for}\quad i=1,2,\ldots,N^*, \\
 {\bm l}(H)\cdot {\bm \phi} = \phi. 
\end{cases}
\end{equation}

Moreover, the solution satisfies 
$\|\nabla\bm{\phi}\|_{H^k} + \delta^{-1}\|\bm{\phi}'\|_{H^k} \leq C\|\nabla\phi\|_{H^k}$.

A key result is that the operator $\Lambda^{(N)}(\zeta,b,\delta)$ provide good approximations in the shallow water 
regime $\delta\ll1$ to the corresponding Dirichlet-to-Neumann map $\Lambda(\zeta,b,\delta)$, which is defined by 

\begin{equation}\label{def-DNmap}
\Lambda(\zeta,b,\delta)\phi := \big(\delta^{-2}\partial_z\Phi-\nabla\zeta\cdot\nabla\Phi\big)\big\vert_{z=\zeta},
\end{equation}

where $\Phi$ is the unique solution to the boundary value problem 

\begin{equation}\label{BVP}
\begin{cases}
\Delta\Phi + \delta^{-2}\partial_z^2\Phi = 0 & \mbox{in}\quad -1+b(\bm{x})<z<\zeta(\bm{x}), \\
\Phi=\phi& \mbox{on}\quad z=\zeta(\bm{x}), \\
\nabla b\cdot\nabla\Phi - \delta^{-2}\partial_z\Phi = 0 & \mbox{on}\quad z=-1+b(\bm{x}).
\end{cases}
\end{equation}

\label{L.L-estimate-D2N}
Let $c, M$ be positive constants and $m, j$ integers such that $m>\frac{n}{2}+1$, $m\geq2(j+1)$, and $1\leq j\leq 2N+1$. 
We assume {\rm (H1)} or {\rm (H2)}. 
There exists a positive constant $C$ such that if $\zeta\in H^m$, $b\in W^{m+1,\infty}$, and $H=1+\zeta-b$ satisfy 

\begin{equation}\label{eq-Hyp}
\begin{cases}
 \|\zeta\|_{H^m}+\|b\|_{W^{m+1,\infty}}\leq M, \\
 H(\bm{x})\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\end{equation}

then for any $\phi\in\mathring{H}^{k+2(j+1)}$ with $0\leq k\leq m-2(j+1)$ and any $\delta\in(0,1]$ we have 

\[
\|\Lambda^{(N)}(\zeta,b,\delta)\phi-\Lambda(\zeta,b,\delta)\phi\|_{H^k}
 \leq C \delta^{2j} \|\nabla \phi\|_{H^{k+2j+1}}.
\]

To this end, we denote 

\begin{equation}\label{def-B}
B(\phi;\zeta,b,\delta)
 := \frac12|\nabla\phi|^2 - \frac12\delta^{2}
  \frac{(\Lambda(\zeta,b,\delta)\phi+\nabla\zeta\cdot\nabla\phi)^2}{1+\delta^2|\nabla\zeta|^2}
\end{equation}

and 

\begin{equation}\label{def-BN}
B^{(N)}(\phi;\zeta,b,\delta)
 := \frac12\bigl( |{\bm u}|^2 + \delta^{-2} w^2 \bigr) - w\Lambda^{(N)}(\zeta,b,\delta)\phi
\end{equation}

with 

\[
\begin{cases}
\displaystyle
\bm{u} :=  ({\bm l}(H) \otimes \nabla)^\mathrm{T}{\bm \phi} - ( {\bm l}^\prime(H) \cdot {\bm\phi})\nabla b, \\
\displaystyle
w :={\bm l}^\prime(H) \cdot {\bm\phi},
\end{cases}
\]

where ${\bm l}^\prime(H) := (0,p_1 H^{p_1-1},\ldots,p_{N^*}H^{p_{N^*}-1})^\mathrm{T}$ 
and ${\bm \phi} := (\phi_0,\phi_1,\ldots,\phi_{N^*})^\mathrm{T}$ is the solution to~\eqref{condition}, 
whose unique existence is guaranteed by Lemma~\ref{L.L-invertible}.

\label{L.Lambda}
Let $c, M$ be positive constants and $m$ an integer such that $m>\frac{n}{2}+1$. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{h}_1, \underline{h}_2, \delta$ satisfying $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, 
if $\zeta\in H^m$, $b\in W^{m,\infty}$, $H_1 = 1 - \underline{h}_1^{-1}\zeta$, and 
$H_2 = 1 + \underline{h}_2^{-1}\zeta - \underline{h}_2^{-1}b$ satisfy 

\begin{equation}\label{eq-Hyp20}
\begin{cases}
 \underline{h}_1^{-1}\|\zeta\|_{H^m} + \underline{h}_2^{-1}\|\zeta\|_{H^m}
  + \underline{h}_2^{-1}\|b\|_{W^{m,\infty}} \leq M, \\
 H_1(\bm{x})\geq c, \quad H_2(\bm{x})\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\end{equation}

then for any $k=0,\pm1,\ldots,\pm(m-1)$ and any $\phi_1,\phi_2 \in \mathring{H}^{k+1}$ there exists a 
unique solution $\bm{\phi}_1=(\phi_{1,0},\bm{\phi}_1')\in \mathring{H}^{k+1}\times(H^{k+1})^N$, 
$\bm{\phi}_2=(\phi_{2,0},\bm{\phi}_2')\in \mathring{H}^{k+1}\times(H^{k+1})^{N^*}$ to the problem 

\begin{equation}\label{Conditions2}
\begin{cases}
 \bm{l}_1(H_1)\cdot\bm{\phi}_1=\phi_1, \quad \mathcal{L}_{1,i}(H_1,\delta,\underline{h}_1)\bm{\phi}_1=0
  \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \bm{l}_2(H_2)\cdot\bm{\phi}_2=\phi_2, \quad \mathcal{L}_{2,i}(H_2,b,\delta,\underline{h}_2)\bm{\phi}_2=0
  \quad\mbox{for}\quad i=1,2,\ldots,N^*.
\end{cases}
\end{equation}

Moreover, the solution satisfies 
$\|\nabla\bm{\phi}_\ell\|_{H^k} + (\underline{h}_\ell\delta)^{-1}\|\bm{\phi}_\ell'\|_{H^k} \leq C\|\nabla\phi_\ell\|_{H^k}$ for $\ell=1,2$.

\label{L.res1}
Let $c, M$ be positive constants and $m, j$ integers such that $m>\frac{n}{2}+1$, $m\geq 2(j+1)$, and $1\leq j\leq 2N+1$. 
We assume {\rm (H1)} or {\rm (H2)}. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{h}_1, \underline{h}_2, \delta$ satisfying $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, 
if $\zeta\in H^m$, $b\in W^{m+1,\infty}$, $H_1 = 1 - \underline{h}_1^{-1}\zeta$, 
and $H_2 = 1 + \underline{h}_2^{-1}\zeta - \underline{h}_2^{-1}b$ satisfy 

\begin{equation}\label{eq-Hyp2}
\begin{cases}
 \underline{h}_1^{-1}\|\zeta\|_{H^m} + \underline{h}_2^{-1}\|\zeta\|_{H^m}
  + \underline{h}_2^{-1}\|b\|_{W^{m+1,\infty}} \leq M, \\
 H_1(\bm{x})\geq c, \quad H_2(\bm{x})\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\end{equation}

then for any $\phi_1,\phi_2 \in \mathring{H}^{k+2(j+1)}$ with $0\leq k\leq m-2(j+1)$ we have 

\[
\begin{cases}
 \|\underline{h}_1\Lambda_1^{(N)}(\zeta,\delta,\underline{h}_1)\phi_1
  - \Lambda_1(\zeta,\delta,\underline{h}_1)\phi_1\|_{H^k}
  \leq C \underline{h}_1(\underline{h}_1\delta)^{2j} \|\nabla \phi_1\|_{H^{k+2j+1}}, \\
 \|\underline{h}_2\Lambda_2^{(N)}(\zeta,b,\delta,\underline{h}_2)\phi_2
  - \Lambda_2(\zeta,b,\delta,\underline{h}_2)\phi_2\|_{H^k}
  \leq C \underline{h}_2(\underline{h}_2\delta)^{2j} \|\nabla \phi_2\|_{H^{k+2j+1}}.
\end{cases}
\]

\label{L.res2}
Let $c, M$ be positive constants and $m$ an integer such that $m\geq 4(N+1)$ and $m>\frac{n}{2}+1$. 
We assume {\rm (H1)} or {\rm (H2)}. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{h}_1, \underline{h}_2, \delta$ satisfying $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, 
if $\zeta\in H^m$, $b\in W^{m+1,\infty}$, $H_1 = 1 - \underline{h}_1^{-1}\zeta$, 
and $H_2 = 1 + \underline{h}_2^{-1}\zeta - \underline{h}_2^{-1}b$ satisfy~\eqref{eq-Hyp2}, 
then for any $\phi_1,\phi_2 \in \mathring{H}^m$ we have 

\[
\begin{cases}
 \|B_1^{(N)}(\phi_1;\zeta,\delta,\underline{h}_1) - B_1(\phi_1;\zeta,\delta,\underline{h}_1)\|_{H^{m-4(N+1)}}
 \leq C \|\nabla \phi_1\|_{H^{m-1}}^2(\underline{h}_1\delta)^{4N+2}, \\
 \|B_2^{(N)}(\phi_2;\zeta,b,\delta,\underline{h}_2) - B_2(\phi_2;\zeta,b,\delta,\underline{h}_2)\|_{H^{m-4(N+1)}}
 \leq C \|\nabla \phi_2\|_{H^{m-1}}^2(\underline{h}_2\delta)^{4N+2}.
\end{cases}
\]

\label{L.elliptic}
Let $c, M$ be positive constants and $m$ an integer such that $m>\frac{n}{2}+1$. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{\rho}_1, \underline{\rho}_2, \underline{h}_1, \underline{h}_2, \delta$ satisfying 
$\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, 
if $\zeta\in H^m$, $b\in W^{m,\infty}$, $H_1 = 1 - \underline{h}_1^{-1}\zeta$, 
and $H_2 = 1 + \underline{h}_2^{-1}\zeta - \underline{h}_2^{-1}b$ satisfy~\eqref{eq-Hyp20}, 
then for any $\bm{f}_1' = (f_{1,1},\ldots,f_{1,N})^\mathrm{T} \in (H^{k})^N$, 
$\bm{f}_2' = (f_{2,1},\ldots,$ $f_{2,N^*})^\mathrm{T} \in (H^{k})^{N^*}$, $\bm{f}_3 \in (H^k)^n$, 
and $f_4\in \mathring H^{k+1} $ with  $k\in\{0,1,\ldots,m-1\}$, 
there exists a solution $(\bm{\varphi}_1,\bm{\varphi}_2)$ to 

\begin{equation}\label{equationvarphi}
\begin{cases}
 \mathcal{L}_{1,i}(H_{1},\delta,\underline{h}_1) {\bm \varphi}_{1} =  f_{1,i} \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \mathcal{L}_{2,i}(H_{2},b,\delta,\underline{h}_2) {\bm \varphi}_{2} = f_{2,i} \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\
 \underline{h}_1\mathcal{L}_{1,0}(H_{1}\delta,\underline{h}_1) {\bm \varphi}_{1}
  + \underline{h}_2\mathcal{L}_{2,0}(H_{2},b,\delta,\underline{h}_2) {\bm \varphi}_{2} = \nabla\cdot \bm{f}_3,\\
 - \underline{\rho}_1{\bm l}_1(H_1) \cdot {\bm \varphi}_1
    + \underline{\rho}_2{\bm l}_2(H_2) \cdot {\bm \varphi}_2 = f_4,
\end{cases}
\end{equation}

satisfying 

\begin{align*}
&\sum_{\ell=1,2}\underline{\rho}_\ell \underline{h}_\ell \bigl(
 \|\nabla\bm{\varphi}_\ell\|_{H^k}^2 + (\underline{h}_\ell\delta)^{-2}\|\bm{\varphi}_\ell'\|_{H^k}^2 \bigr) \\
&\leq C\biggl( \sum_{\ell=1,2}\underline{\rho}_\ell \underline{h}_\ell
 \min\bigl\{ \|\bm{f}_\ell'\|_{H^{k-1}}^2, (\underline{h}_\ell\delta)^2 \|\bm{f}_\ell'\|_{H^k}^2 \bigr\} \\
&\qquad
 + \min\biggl\{\frac{\underline{\rho}_1}{\underline{h}_1},\frac{\underline{\rho}_2}{\underline{h}_2} \biggr\}
  \|\bm{f}_3\|_{H^k}^2
 + \min\biggl\{\frac{\underline{h}_1}{\underline{\rho}_1},\frac{\underline{h}_2}{\underline{\rho}_2} \biggr\}
  \|\nabla f_4\|_{H^k}^2 \biggr).
\end{align*}

Moreover, the solution is unique up to an additive constant of the form 
$(\mathcal{C}\underline{\rho}_2,\mathcal{C}\underline{\rho}_1)$ to $(\varphi_{1,0},\varphi_{2,0})$.

\begin{equation}\label{equationvarphi}
\begin{cases}
 \mathcal{L}_{1,i}(H_{1},\delta,\underline{h}_1) {\bm \varphi}_{1} =  f_{1,i} \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \mathcal{L}_{2,i}(H_{2},b,\delta,\underline{h}_2) {\bm \varphi}_{2} = f_{2,i} \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\
 \underline{h}_1\mathcal{L}_{1,0}(H_{1}\delta,\underline{h}_1) {\bm \varphi}_{1}
  + \underline{h}_2\mathcal{L}_{2,0}(H_{2},b,\delta,\underline{h}_2) {\bm \varphi}_{2} = \nabla\cdot \bm{f}_3,\\
 - \underline{\rho}_1{\bm l}_1(H_1) \cdot {\bm \varphi}_1
    + \underline{\rho}_2{\bm l}_2(H_2) \cdot {\bm \varphi}_2 = f_4,
\end{cases}
\end{equation}

The existence and uniqueness up to an additive constant of the solution has been given in the companion 
paper~\cite[Lemma~6.4]{DucheneIguchi2020}. 
We focus here on the derivation of uniform estimates. 

By direct rescaling within the proof of~\cite[Lemma~6.1]{DucheneIguchi2020}, we infer that 

\[
(L_\ell\bm{\varphi}_\ell,\bm{\varphi}_\ell)_{L^2}
\simeq \|\nabla\bm{\varphi}_\ell\|_{L^2}^2 + (\underline{h}_\ell\delta)^{-2}\|\bm{\varphi}_\ell'\|_{L^2}^2
\]

for $\ell=1,2$. 
We note the identities 

\[
\begin{cases}
 L_1\bm{\varphi}_1 = \bm{l}_1\mathcal{L}_{1,0}\bm{\varphi}_1
  + (0,\mathcal{L}_{1,1}\bm{\varphi}_1,\ldots,\mathcal{L}_{1,N}\bm{\varphi}_1)^\mathrm{T}, \\
 L_2\bm{\varphi}_2 = \bm{l}_2\mathcal{L}_{2,0}\bm{\varphi}_2
  + (0,\mathcal{L}_{2,1}\bm{\varphi}_2,\ldots,\mathcal{L}_{2,N^*}\bm{\varphi}_2)^\mathrm{T},
\end{cases}
\]

so that for the solution $(\bm{\varphi}_1,\bm{\varphi}_2)$ to~\eqref{equationvarphi} we have 

\begin{align}\label{EE-identity1}
\sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell (L_\ell\bm{\varphi}_\ell,\bm{\varphi}_\ell)_{L^2}
&= \sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell
 (\mathcal{L}_{\ell,0}\bm{\varphi}_\ell,\bm{l}_\ell\cdot\bm{\varphi}_\ell)_{L^2}
 + \sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell (\bm{f}_\ell',\bm{\varphi}_\ell')_{L^2} \\
&=: I_1+I_2. \nonumber
\end{align}

Therefore, it is sufficient to evaluate $I_1$ and $I_2$. 
As for the term $I_2$ we have 

\begin{align*}
|(\bm{f}_\ell',\bm{\varphi}_\ell')_{L^2}|
&\leq \min\{ \|\bm{f}_\ell'\|_{H^{-1}}\|\bm{\varphi}_\ell'\|_{H^1}, 
\|\bm{f}_\ell'\|_{L^2}\|\bm{\varphi}_\ell'\|_{L^2} \} \\
&\leq \min\{ \|\bm{f}_\ell'\|_{H^{-1}}, (\underline{h}_\ell\delta)\|\bm{f}_\ell'\|_{L^2} \}
( \|\nabla\bm{\varphi}_\ell\|_{L^2} + (\underline{h}_\ell\delta)^{-1}\|\bm{\varphi}_\ell'\|_{L^2} ).
\end{align*}

As for the term $I_1$, we note the trivial identities 

\begin{align*}
&\sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell
 (\mathcal{L}_{\ell,0}\bm{\varphi}_\ell,\bm{l}_\ell\cdot\bm{\varphi}_\ell)_{L^2} \\
&= 
\begin{cases}
 (\underline{h}_1\mathcal{L}_{1,0}\bm{\varphi}_1+\underline{h}_2\mathcal{L}_{2,0}\bm{\varphi}_2,
  \underline{\rho}_1\bm{l}_1\cdot\bm{\varphi}_1)_{L^2}
 + (\underline{h}_2\mathcal{L}_{2,0}\bm{\varphi}_2,
  \underline{\rho}_2\bm{l}_2\cdot\bm{\varphi}_2-\underline{\rho}_1\bm{l}_1\cdot\bm{\varphi}_1)_{L^2}, \\
 (\underline{h}_1\mathcal{L}_{1,0}\bm{\varphi}_1+\underline{h}_2\mathcal{L}_{2,0}\bm{\varphi}_2,
  \underline{\rho}_2\bm{l}_2\cdot\bm{\varphi}_2)_{L^2}
 + (\underline{h}_1\mathcal{L}_{1,0}\bm{\varphi}_1,
  \underline{\rho}_1\bm{l}_1\cdot\bm{\varphi}_1-\underline{\rho}_2\bm{l}_2\cdot\bm{\varphi}_2)_{L^2}.
\end{cases}
\end{align*}

Therefore, the term $I_1$ in~\eqref{EE-identity1} can be expressed in two ways as 

\[
I_1 = 
\begin{cases}
 \underline{\rho}_1(\nabla\cdot\bm{f}_3,\bm{l}_1\cdot\bm{\varphi}_1)_{L^2}
  + \underline{h}_2(\mathcal{L}_{2,0}\bm{\varphi}_2,f_4)_{L^2}, \\
 \underline{\rho}_2(\nabla\cdot\bm{f}_3,\bm{l}_2\cdot\bm{\varphi}_2)_{L^2}
  - \underline{h}_1(\mathcal{L}_{1,0}\bm{\varphi}_1,f_4)_{L^2}.
\end{cases}
\]

By the linearity of~\eqref{equationvarphi} it is sufficient to evaluate it in the case 
$f_4=0$ and in the case $\bm{f}_3=\bm{0}$, separately. 
In the case $f_4=0$, we evaluate it as 

\begin{align*}
|I_1|
&\leq \min\{ \underline{\rho}_1\|\bm{f}_3\|_{L^2}\|\nabla(\bm{l}_1\cdot\bm{\varphi}_1)\|_{L^2},
  \underline{\rho}_2\|\bm{f}_3\|_{L^2}\|\nabla(\bm{l}_2\cdot\bm{\varphi}_2)\|_{L^2} \} \\
&= \min\biggl\{ \sqrt{\frac{\underline{\rho}_1}{\underline{h}_1}}\|\bm{f}_3\|_{L^2}
  \sqrt{\underline{\rho}_1\underline{h}_1}\|\nabla(\bm{l}_1\cdot\bm{\varphi}_1)\|_{L^2}, 
 \sqrt{\frac{\underline{\rho}_2}{\underline{h}_2}}\|\bm{f}_3\|_{L^2}
  \sqrt{\underline{\rho}_2\underline{h}_2}\|\nabla(\bm{l}_2\cdot\bm{\varphi}_2)\|_{L^2} \biggr\} \\
&\lesssim \min\biggl\{ \sqrt{\frac{\underline{\rho}_1}{\underline{h}_1}},
  \sqrt{\frac{\underline{\rho}_2}{\underline{h}_2}} \biggr\} \|\bm{f}_3\|_{L^2}
 \sum_{\ell=1,2}\sqrt{\underline{\rho}_\ell\underline{h}_\ell}
 ( \|\nabla\bm{\varphi}_\ell\|_{L^2} + \|\bm{\varphi}_\ell'\|_{L^2} ).
\end{align*}

In the case $\bm{f}_3=\bm{0}$ we evaluate it as 

\begin{align*}
|I_1|
&\lesssim \min\{ \underline{h}_1\|\nabla\bm{\varphi}_1\|_{L^2}\|\nabla f_4\|_{L^2}, 
 \underline{h}_2( \|\nabla\bm{\varphi}_2\|_{L^2}+\|\bm{\varphi}_2'\|_{L^2})\|\nabla f_4\|_{L^2} \} \\
&= \min\biggl\{ \sqrt{\frac{\underline{h}_1}{\underline{\rho}_1}}\|\nabla f_4\|_{L^2}
  \sqrt{\underline{\rho}_1\underline{h}_1}\|\nabla\bm{\varphi}_1\|_{L^2}, 
 \sqrt{\frac{\underline{h}_2}{\underline{\rho}_2}}\|\nabla f_4\|_{L^2}
  \sqrt{\underline{\rho}_2\underline{h}_2} (\|\nabla\bm{\varphi}_1\|_{L^2}+\|\bm{\varphi}_2'\|_{L^2}) \biggr\} \\
&\leq \min\biggl\{ \sqrt{\frac{\underline{h}_1}{\underline{\rho}_1}},
  \sqrt{\frac{\underline{h}_2}{\underline{\rho}_2}} \biggr\} \|\nabla f_4\|_{L^2}
 \sum_{\ell=1,2}\sqrt{\underline{\rho}_\ell\underline{h}_\ell}
 ( \|\nabla\bm{\varphi}_\ell\|_{L^2} + \|\bm{\varphi}_\ell'\|_{L^2} ).
\end{align*}

From the above estimates we deduce immediately the desired inequality for $k=0$. 


In order to obtain the desired inequality on derivatives, we let $k\in\{1,2,\ldots,m-1\}$ and $\beta$ be a 
multi-index such that $1\leq|\beta|\leq k$. 
Applying the differential operator $\partial^\beta$ to~\eqref{equationvarphi}, we have 

\[
\begin{cases}
 \mathcal{L}_{1,i} \partial^\beta{\bm \varphi}_{1}
  =  \partial^\beta f_{1,i} + f_{1,i,\beta} \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \mathcal{L}_{2,i} \partial^\beta{\bm \varphi}_{2}
  = \partial^\beta f_{2,i} + f_{2,i,\beta} \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\
 \underline{h}_1\mathcal{L}_{1,0} \partial^\beta{\bm \varphi}_{1}
   + \underline{h}_2\mathcal{L}_{2,0} \partial^\beta{\bm \varphi}_{2}
  = \nabla\cdot (\partial^\beta \bm{f}_3 + \underline{h}_1\bm{f}_{3,1,\beta} + \underline{h}_2\bm{f}_{3,2,\beta}), \\
 - \underline{\rho}_1{\bm l}_1 \cdot \partial^\beta{\bm \varphi}_1
    + \underline{\rho}_2{\bm l}_2 \cdot \partial^\beta{\bm \varphi}_2
   = \partial^\beta f_4 + \underline{\rho}_1f_{4,1,\beta} + \underline{\rho}_2f_{4,2,\beta},
\end{cases}
\]

where 

\[
\begin{cases}
 f_{1,i,\beta} := -[\partial^\beta, \mathcal{L}_{1,i}(H_{1},\delta,\underline{h}_1)]{\bm \varphi}_{1}
  \quad\mbox{for}\quad i=1,2,\ldots,N, \\ 
 f_{2,i,\beta} := -[\partial^\beta, \mathcal{L}_{2,i}(H_{2},b,\delta,\underline{h}_2)]{\bm \varphi}_{2}
  \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\ 
 \nabla\cdot \bm{f}_{3,1,\beta} := -[\partial^\beta, \mathcal{L}_{1,0}(H_{1},\delta,\underline{h}_1)]{\bm \varphi}_{1}, \\
 \nabla\cdot \bm{f}_{3,2,\beta} := -[\partial^\beta, \mathcal{L}_{2,0}(H_{2},b,\delta,\underline{h}_2)]{\bm \varphi}_{2} , \\
 f_{4,1,\beta} :=  [\partial^\beta, {\bm l}_1(H_1) ] \cdot {\bm \varphi}_1, \\
 f_{4,2,\beta} := -[\partial^\beta, {\bm l}_2(H_2) ] \cdot {\bm \varphi}_2.
\end{cases}
\]

We put $\bm{f}_{1,\beta}=(0,f_{1,1,\beta},\ldots,f_{1,N,\beta})$ and $\bm{f}_{2,\beta}=(0,f_{2,1,\beta},\ldots,f_{2,N^*,\beta})$. 
Then, with a suitable decomposition $\bm{f}_{\ell,\beta} = \bm{f}_{\ell,\beta}^\mathrm{high} + \bm{f}_{\ell,\beta}^\mathrm{low}$ 
for $\ell=1,2$, we see that 

\begin{align*}
\|\bm{f}_{\ell,\beta}^\mathrm{high}\|_{H^{-1}} + (\underline{h}_\ell\delta)\|\bm{f}_{\ell,\beta}^\mathrm{low}\|_{L^2}
 + \|\bm{f}_{3,\ell,\beta}\|_{L^2} + \|\nabla f_{4,\ell}\|_{L^2}
\lesssim \|\nabla\bm{\varphi}_\ell\|_{H^{k-1}} + (\underline{h}_\ell\delta)^{-1}\|\bm{\varphi}_\ell'\|_{H^{k-1}}
\end{align*}

for $\ell=1,2$. 
Therefore, in view of the linearity of~\eqref{equationvarphi} the desired inequality for $k\geq1$ follows by induction on $k$.

\[
\begin{cases}
 \mathcal{L}_{1,i} \partial^\beta{\bm \varphi}_{1}
  =  \partial^\beta f_{1,i} + f_{1,i,\beta} \quad\mbox{for}\quad i=1,2,\ldots,N, \\
 \mathcal{L}_{2,i} \partial^\beta{\bm \varphi}_{2}
  = \partial^\beta f_{2,i} + f_{2,i,\beta} \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\
 \underline{h}_1\mathcal{L}_{1,0} \partial^\beta{\bm \varphi}_{1}
   + \underline{h}_2\mathcal{L}_{2,0} \partial^\beta{\bm \varphi}_{2}
  = \nabla\cdot (\partial^\beta \bm{f}_3 + \underline{h}_1\bm{f}_{3,1,\beta} + \underline{h}_2\bm{f}_{3,2,\beta}), \\
 - \underline{\rho}_1{\bm l}_1 \cdot \partial^\beta{\bm \varphi}_1
    + \underline{\rho}_2{\bm l}_2 \cdot \partial^\beta{\bm \varphi}_2
   = \partial^\beta f_4 + \underline{\rho}_1f_{4,1,\beta} + \underline{\rho}_2f_{4,2,\beta},
\end{cases}
\]

\[
\begin{cases}
 f_{1,i,\beta} := -[\partial^\beta, \mathcal{L}_{1,i}(H_{1},\delta,\underline{h}_1)]{\bm \varphi}_{1}
  \quad\mbox{for}\quad i=1,2,\ldots,N, \\ 
 f_{2,i,\beta} := -[\partial^\beta, \mathcal{L}_{2,i}(H_{2},b,\delta,\underline{h}_2)]{\bm \varphi}_{2}
  \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\ 
 \nabla\cdot \bm{f}_{3,1,\beta} := -[\partial^\beta, \mathcal{L}_{1,0}(H_{1},\delta,\underline{h}_1)]{\bm \varphi}_{1}, \\
 \nabla\cdot \bm{f}_{3,2,\beta} := -[\partial^\beta, \mathcal{L}_{2,0}(H_{2},b,\delta,\underline{h}_2)]{\bm \varphi}_{2} , \\
 f_{4,1,\beta} :=  [\partial^\beta, {\bm l}_1(H_1) ] \cdot {\bm \varphi}_1, \\
 f_{4,2,\beta} := -[\partial^\beta, {\bm l}_2(H_2) ] \cdot {\bm \varphi}_2.
\end{cases}
\]

\begin{equation}\label{commutator-dt}
\begin{cases}
 f_{1,i} := -[\partial_t, \mathcal{L}_{1,i}(H_{1},\delta,\underline{h}_1)]\bm{\phi}_{1}
  \quad\mbox{for}\quad i=1,2,\ldots,N, \\ 
 f_{2,i} := -[\partial_t, \mathcal{L}_{2,i}(H_{2},b,\delta,\underline{h}_2)]\bm{\phi}_{2}
  \quad\mbox{for}\quad i=1,2,\ldots,N^*, \\ 
 \bm{f}_{3} := (\bm{u}_2-\bm{u}_1)\partial_t\zeta , \\
 f_{4} := \frac12\underline{\rho}_1\bigl( |{\bm u}_1|^2 + (\underline{h}_1\delta)^{-2} w_1^2 \bigr)
  - \frac12\underline{\rho}_2\bigl( |{\bm u}_2|^2 + (\underline{h}_2\delta)^{-2} w_2^2 \bigr)
  - \zeta.
\end{cases}
\end{equation}

\begin{equation}\label{Kakinuma-approx}
\begin{cases}
 \displaystyle
 {\bm l}_1(H_1)\partial_t\zeta + \underline{h}_1 L_1(H_1,\delta,\underline{h}_1){\bm \phi}_1 = {\bm 0}, \\
 \displaystyle
 {\bm l}_2(H_2)\partial_t\zeta - \underline{h}_2 L_2(H_2,b,\delta,\underline{h}_2){\bm \phi}_2 = {\bm 0}, \\
 \underline{\rho}_1\bigl\{ {\bm l}_1(H_1) \cdot \partial_t{\bm \phi}_1 
   + \frac12\bigl( |{\bm u}_1|^2 + (\underline{h}_1\delta)^{-2} w_1^2 \bigr) \bigr\} \\
 \quad
 - \underline{\rho}_2\bigl\{ {\bm l}_2(H_2) \cdot \partial_t{\bm \phi}_2 
  + \frac12\bigl( |{\bm u}_2|^2 +  (\underline{h}_2\delta)^{-2} w_2^2 \bigr) \bigr\} 
 - \zeta = 0, 
\end{cases}
\end{equation}

For $\ell=1,2$, the coefficient matrices of the principal part and the singular part with respect to 
the small parameter $\delta_\ell=\underline{h}_\ell\delta$ of the operator $L_{\ell}$ are denoted by 
$A_\ell(H_\ell)$ and $C_\ell(H_\ell)$, respectively, that is, 

\begin{equation}\label{def-A}
\begin{cases}
 \displaystyle
 A_1(H_1) := \left( \frac{1}{2(i+j)+1}H_1^{2(i+j)+1} \right)_{0\leq i,j\leq N}, \\
 \displaystyle
 A_2(H_2) := \left( \frac{1}{p_i+p_j+1}H_2^{p_i+p_j+1} \right)_{0\leq i,j\leq N^*}, 
\end{cases}
\end{equation}

and 

\begin{equation}\label{def-C}
\begin{cases}
 \displaystyle
 C_1(H_1) := \left( \frac{4ij}{2(i+j)-1}H_1^{2(i+j)-1} \right)_{0\leq i,j\leq N}, \\
 \displaystyle
 C_2(H_2) := \left( \frac{p_ip_j}{p_i+p_j-1}H_2^{p_i+p_j-1} \right)_{0\leq i.j\leq N^*}.
\end{cases}
\end{equation}

\begin{equation}\label{def-A}
\begin{cases}
 \displaystyle
 A_1(H_1) := \left( \frac{1}{2(i+j)+1}H_1^{2(i+j)+1} \right)_{0\leq i,j\leq N}, \\
 \displaystyle
 A_2(H_2) := \left( \frac{1}{p_i+p_j+1}H_2^{p_i+p_j+1} \right)_{0\leq i,j\leq N^*}, 
\end{cases}
\end{equation}

\begin{equation}\label{def-C}
\begin{cases}
 \displaystyle
 C_1(H_1) := \left( \frac{4ij}{2(i+j)-1}H_1^{2(i+j)-1} \right)_{0\leq i,j\leq N}, \\
 \displaystyle
 C_2(H_2) := \left( \frac{p_ip_j}{p_i+p_j-1}H_2^{p_i+p_j-1} \right)_{0\leq i.j\leq N^*}.
\end{cases}
\end{equation}

\begin{equation}\label{def-B2}
\begin{cases}
 \displaystyle
 B_2(H_2) := \left( \frac{p_j}{p_i+p_j}H_2^{p_i+p_j} \right)_{0\leq i,j\leq N^*}, \\
 \tilde{B}_2(H_2) := B_2(H_2) - B_2(H_2)^\mathrm{T}, \\
 \tilde{C}_2(H_2,\underline{h}_2^{-1}b) := |\underline{h}_2^{-1}\nabla b|^2 C_2(H_2) + \underline{h}_2^{-1}(\Delta b)B_2(H_2). 
\end{cases}
\end{equation}

After neglecting lower order terms, the linearized equations have the form 

\begin{equation}\label{linear-Kakinuma}
\begin{cases}
 \displaystyle
 {\bm l}_1(H_1)(\partial_t+\bm{u}_1\cdot\nabla)\dot{\zeta}
  + \underline{h}_1 L_1^\mathrm{pr}(H_1,\delta,\underline{h}_1)\dot{\bm{\phi}}_1 = \dot{{\bm f}}_1, \\
 \displaystyle
 {\bm l}_2(H_2)(\partial_t+\bm{u}_2\cdot\nabla)\dot{\zeta}
  - \underline{h}_2 L_2^\mathrm{pr}(H_2,\delta,\underline{h}_2)\dot{\bm{\phi}}_2 = \dot{{\bm f}}_2, \\
 \underline{\rho}_1{\bm l}_1(H_1)\cdot( \partial_t+\bm{u}_1\cdot\nabla )\dot{\bm{\phi}}_1 
  - \underline{\rho}_2{\bm l}_2(H_2)\cdot( \partial_t+\bm{u}_1\cdot\nabla )\dot{\bm{\phi}}_2 
  - a\dot{\zeta} = \dot{f}_0,
\end{cases}
\end{equation}

where the function $a$ is defined by~\eqref{def-a}.

\label{L.A0-coercive}
Let $c, M, \underline{h}_\mathrm{min}$ be positive constants. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{\rho}_1,\underline{\rho}_2,\underline{h}_1,\underline{h}_2,\delta$ satisfying the condition 
$\underline{h}_\mathrm{min} \leq \underline{h}_1,\underline{h}_2$, if $H_1,H_2,\bm{u}_1,\bm{u}_2$, and the function $a$ satisfy 

\begin{equation}\label{conditions-linear1}
\begin{cases}
 \displaystyle
 \sum_{\ell=1,2}\bigl( \|H_\ell\|_{L^\infty} + \sqrt{ \underline{\rho}_\ell\underline{h}_\ell }
  \|\bm{u}_\ell\|_{L^\infty} \bigr) + \|a\|_{L^\infty} \leq M, \\
 \displaystyle
 a(\bm{x}) - \frac{ \underline{\rho}_1\underline{\rho}_2 }{ \underline{\rho}_1\underline{h}_2H_2(\bm{x})\alpha_2
  + \underline{\rho}_2\underline{h}_1H_1(\bm{x})\alpha_1 }|\bm{u}_2(\bm{x})-\bm{u}_1(\bm{x})|^2 \geq c, \\
 H_1(\bm{x}) \geq c, \quad H_2(\bm{x}) \geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\end{equation}

then for any $\dot{\bm{U}} = (\dot{\zeta},\dot{\bm{\phi}}_1,\dot{\bm{\phi}}_2)^\mathrm{T} \in 
L^2\times(\mathring{H}^1\times(H^1)^N)\times(\mathring{H}^1\times(H^1)^{N^*})$ we have 

\[
C^{-1}\mathscr{E}(\dot{\bm{U}}) \leq (\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2}
\leq C\mathscr{E}(\dot{\bm{U}}). 
\]

\begin{equation}\label{conditions-linear1}
\begin{cases}
 \displaystyle
 \sum_{\ell=1,2}\bigl( \|H_\ell\|_{L^\infty} + \sqrt{ \underline{\rho}_\ell\underline{h}_\ell }
  \|\bm{u}_\ell\|_{L^\infty} \bigr) + \|a\|_{L^\infty} \leq M, \\
 \displaystyle
 a(\bm{x}) - \frac{ \underline{\rho}_1\underline{\rho}_2 }{ \underline{\rho}_1\underline{h}_2H_2(\bm{x})\alpha_2
  + \underline{\rho}_2\underline{h}_1H_1(\bm{x})\alpha_1 }|\bm{u}_2(\bm{x})-\bm{u}_1(\bm{x})|^2 \geq c, \\
 H_1(\bm{x}) \geq c, \quad H_2(\bm{x}) \geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\end{equation}

This lemma can be shown along with the proof of~\cite[Lemma 7.4]{DucheneIguchi2020}. 
For the sake of completeness, we sketch the proof. 
We first note that 

\begin{align*}
(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2}
&= (a\dot{\zeta},\dot{\zeta})_{L^2}
 + \sum_{\ell=1,2} \{ \underline{\rho}_\ell\underline{h}_\ell (L_\ell^\mathrm{pr}\dot{\bm{\phi}}_\ell, \dot{\bm{\phi}}_\ell)_{L^2}
 + 2\underline{\rho}_\ell (\theta_\ell\bm{l}_\ell\cdot(\bm{v}\cdot\nabla)\dot{\bm{\phi}}_\ell,\dot{\zeta})_{L^2} \} \\
&= (a\dot{\zeta},\dot{\zeta})_{L^2}
 + \sum_{\ell=1,2} \biggl\{ \underline{\rho}_\ell\underline{h}_\ell \biggl(
  \sum_{l=1}^n(A_\ell\partial_l\dot{\bm{\phi}}_\ell,\partial_l\dot{\bm{\phi}}_\ell)_{L^2}
   + (\underline{h}_\ell\delta)^{-2}(C_\ell\dot{\bm{\phi}}_\ell,\dot{\bm{\phi}}_\ell)_{L^2} \biggr) \\
&\makebox[9em]{}
 + 2\underline{\rho}_\ell(\theta_\ell\bm{v}\cdot(\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell, \dot{\zeta})_{L^2}
 \biggr\},
\end{align*}

where we used the identity $\bm{a}\cdot(\bm{v}\cdot\nabla)\bm{\varphi} = \bm{v}\cdot(\bm{a}\otimes\nabla)^\mathrm{T}\bm{\varphi}$. 
On the other hand, we can put 

\[
\begin{pmatrix}
 q_\ell(H_\ell) & \bm{q}_\ell(H_\ell)^\mathrm{T} \\
 -\bm{q}_\ell(H_\ell) & Q_\ell(H_\ell)
\end{pmatrix}
:= 
\begin{pmatrix}
 0 & \bm{l}_\ell(H_\ell)^\mathrm{T} \\
 -\bm{l}_\ell(H_\ell) & A_\ell(H_\ell)
\end{pmatrix}^{-1}
\]

for $\ell=1,2$. 
Then, we see that $q_\ell(H_\ell)=H_\ell\alpha_\ell$ and that $Q_\ell(H_\ell)$ is nonnegative. 
Moreover, the identity 

\begin{equation}\label{decomposition-A}
A_\ell(H_\ell)\bm{\varphi}_\ell\cdot\bm{\varphi}_\ell
= q_\ell(H_\ell)(\bm{l}_\ell(H_\ell) \cdot \bm{\varphi}_\ell)^2
 + Q_\ell(H_\ell)A_\ell(H_\ell)\bm{\varphi}_\ell \cdot A_\ell(H_\ell)\bm{\varphi}_\ell
\end{equation}

holds for any $\bm{\varphi}_\ell$. 
Therefore, 

\begin{align*}
\sum_{l=1}^n(A_\ell\partial_l\dot{\bm{\phi}}_\ell,\partial_l\dot{\bm{\phi}}_\ell)_{L^2}
&= \sum_{l=1}^n\{ (q_\ell\bm{l}_\ell\cdot\partial_l\dot{\bm{\phi}}_\ell,\bm{l}_\ell\cdot\partial_l\dot{\bm{\phi}}_\ell)_{L^2}
 + (Q_\ell A_\ell\partial_l\dot{\bm{\phi}}_\ell,A_\ell\partial_l\dot{\bm{\phi}}_\ell)_{L^2} \} \\
&= (H_\ell\alpha_\ell (\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell, 
  (\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell)_{L^2}
 + \sum_{l=1}^n(Q_\ell A_\ell\partial_l\dot{\bm{\phi}}_\ell,A_\ell\partial_l\dot{\bm{\phi}}_\ell)_{L^2},
\end{align*}

so that 

\begin{align*}
(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2}
&= (a\dot{\zeta},\dot{\zeta})_{L^2}
 + \sum_{\ell=1,2} \{ \underline{\rho}_\ell\underline{h}_\ell
   (H_\ell\alpha_\ell (\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell, 
    (\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell)_{L^2} \\
&\makebox[8em]{}
  + 2\underline{\rho}_\ell(\theta_\ell\bm{v}\cdot(\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell, \dot{\zeta})_{L^2} \} \\
&\quad\;
 + \sum_{\ell=1,2} \underline{\rho}_\ell\underline{h}_\ell \biggl\{
  \sum_{l=1}^n (Q_\ell A_\ell\partial_l\dot{\bm{\phi}}_\ell,A_\ell\partial_l\dot{\bm{\phi}}_\ell)_{L^2}
  + (\underline{h}_\ell\delta)^{-2}(C_\ell\dot{\bm{\phi}}_\ell,\dot{\bm{\phi}}_\ell)_{L^2} \biggr\} \\
&=: I_1+I_2.
\end{align*}

We proceed to evaluate $I_1$. 

\begin{align*}
I_1 &\geq \int_{\mathbf{R}^n}\biggl\{ a\dot{\zeta}^2
 + \sum_{\ell=1,2}\bigl(
  \underline{\rho}_\ell\underline{h}_\ell H_\ell\alpha_\ell|(\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell|^2
 - 2\underline{\rho}_\ell\theta_\ell|\bm{v}||(\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell||\dot{\zeta}| \bigr)
 \biggr\}\mathrm{d}\bm{x} \\
&= \int_{\mathbf{R}^n} \mathfrak{A}_0
\begin{pmatrix}
 \dot{\zeta} \\ 
 \sqrt{ \underline{\rho}_1\underline{h}_1 } |(\bm{l}_1\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_1| \\
 \sqrt{ \underline{\rho}_2\underline{h}_2 } |(\bm{l}_2\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_2|
\end{pmatrix}
\cdot
\begin{pmatrix}
 \dot{\zeta} \\ 
 \sqrt{ \underline{\rho}_1\underline{h}_1 } |(\bm{l}_1\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_1| \\
 \sqrt{ \underline{\rho}_2\underline{h}_2 } |(\bm{l}_2\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_2|
\end{pmatrix}
\mathrm{d}\bm{x},
\end{align*}

where the matrix $\mathfrak{A}_0$ is given by 

\[
\mathfrak{A}_0 = 
\begin{pmatrix}
 a & - \sqrt{\underline{\rho}_1/\underline{h}_1} \theta_1|\bm{v}|
  & - \sqrt{\underline{\rho}_2/\underline{h}_2} \theta_2|\bm{v}| \\
 - \sqrt{\underline{\rho}_1/\underline{h}_1} \theta_1|\bm{v}| & H_1\alpha_1 & 0 \\
 - \sqrt{\underline{\rho}_2/\underline{h}_2} \theta_2|\bm{v}| & 0 & H_2\alpha_2
\end{pmatrix}.
\]

Here, we see that 

\begin{align*}
\det\mathfrak{A}_0
= H_1H_2\alpha_1\alpha_2\biggl( a
 - \frac{ \underline{\rho}_1\underline{\rho}_2 }{ \underline{\rho}_1\underline{h}_2H_2\alpha_2
  + \underline{\rho}_2\underline{h}_1H_1\alpha_1 }|\bm{v}|^2 \biggr)
\geq c^3\alpha_1\alpha_2 > 0,
\end{align*}

so that $\mathfrak{A}_0$ is positive definite by Sylvester's criterion. 
Moreover, $\operatorname{tr}\mathfrak{A}_0 \leq \max\{1,\alpha_1,\alpha_2\}\, M \lesssim 1$ 
and the minimal eigenvalue of the matrix $\mathfrak{A}_0$ is bounded from below by 
$4\det\mathfrak{A}_0/(\operatorname{tr}\mathfrak{A}_0)^2 \gtrsim 1$. 
Therefore, we obtain 

\[
I_1 \gtrsim \int_{\mathbf{R}^n} \biggl( \dot{\zeta}^2
 + \sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell H_\ell\alpha_\ell
  |(\bm{l}_\ell\otimes\nabla)^\mathrm{T}\dot{\bm{\phi}}_\ell|^2 \biggr)\mathrm{d}\bm{x}.
\]

As for $I_2$, it is easy to see that 
$(C_\ell\dot{\bm{\phi}}_\ell,\dot{\bm{\phi}}_\ell)_{L^2} \simeq \|\dot{\bm{\phi}}_\ell'\|_{L^2}^2$ for $\ell=1,2$. 
Summarizing the above estimates and using the decomposition~\eqref{decomposition-A} again, we obtain 
$(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2} \gtrsim \mathscr{E}(\dot{\bm{U}})$. 


In order to obtain the estimate of $(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2}$ from above, 
it is sufficient to show that each element of the matrix $\mathfrak{A}_0$ is uniformly bounded. 
Since $\theta_1+\theta_2=1$, we have 

\[
\begin{cases}
 \sqrt{\underline{\rho}_1/\underline{h}_1} \theta_1|\bm{v}|
  \leq \underline{h}_1^{-1}\sqrt{\underline{\rho}_1\underline{h}_1}|\bm{u}_1|
   + \sqrt{\underline{\rho}_1/\underline{h}_1} \theta_1|\bm{u}_2|, \\
 \sqrt{\underline{\rho}_2/\underline{h}_2} \theta_2|\bm{v}|
  \leq \sqrt{\underline{\rho}_2/\underline{h}_2} \theta_2|\bm{u}_1|
   + \underline{h}_2^{-1}\sqrt{\underline{\rho}_2\underline{h}_2}|\bm{u}_2|.
\end{cases}
\]

Here, we see that 

\begin{align*}
\sqrt{\underline{\rho}_1/\underline{h}_1} \theta_1|\bm{u}_2|
&= \frac{1}{\underline{h}_2}\sqrt{\frac{H_1\alpha_1}{H_2\alpha_2}}
 \frac{\sqrt{ (\underline{\rho}_1\underline{h}_2H_2\alpha_2) (\underline{\rho}_2\underline{h}_1H_1\alpha_1) }}{
  \underline{\rho}_1\underline{h}_2H_2\alpha_2+\underline{\rho}_2\underline{h}_1H_1\alpha_1}
 \sqrt{\underline{\rho}_2\underline{h}_2}|\bm{u}_2| \\
&\leq \frac{1}{2\underline{h}_2}\sqrt{\frac{H_1\alpha_1}{H_2\alpha_2}}\sqrt{\underline{\rho}_2\underline{h}_2}|\bm{u}_2| \\
&\leq \frac{1}{2\underline{h}_\mathrm{min} \sqrt{\frac{M\alpha_1}{c\alpha_2}}M}
 \lesssim 1.
\end{align*}

Similarly, we have $\sqrt{\underline{\rho}_2/\underline{h}_2} \theta_2|\bm{u}_1| \lesssim 1$. 
Therefore, we obtain 
$(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2} \lesssim \mathscr{E}(\dot{\bm{U}})$.

We deduce from~\eqref{Kakinuma-MF} that 

\begin{align*}
&\frac{\mathrm{d}}{\mathrm{d}t}(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2} \\
&= ([\partial_t,\mathscr{A}_0^\mathrm{mod}]\dot{\bm{U}},\dot{\bm{U}})_{L^2}
 + 2(\mathscr{A}_0^\mathrm{mod}\partial_t\dot{\bm{U}},\dot{\bm{U}})_{L^2} \\
&= ([\partial_t,\mathscr{A}_0^\mathrm{mod}]\dot{\bm{U}},\dot{\bm{U}})_{L^2}
 + 2((\partial_t+\bm{u}\cdot\nabla)\dot{\bm{U}},\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}})_{L^2}
 - 2((\bm{u}\cdot\nabla)\dot{\bm{U}},\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}})_{L^2} \\
&= ([\partial_t,\mathscr{A}_0^\mathrm{mod}]\dot{\bm{U}},\dot{\bm{U}})_{L^2}
 - 2((\bm{u}\cdot\nabla)\dot{\bm{U}},\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}})_{L^2}
 + 2((\partial_t+\bm{u}\cdot\nabla)\dot{\bm{U}},\dot{\bm{F}})_{L^2} \\
&=: I_1+I_2+I_3,
\end{align*}

where we used the fact that $\mathscr{A}_0^\mathrm{mod}$ is a symmetric operator in $L^2$ and that $\mathscr{A}_1$ 
is a skew-symmetric matrix. 
As for $I_1$, we have 

\begin{align*}
I_1 = ((\partial_t a)\dot{\zeta},\dot{\zeta})_{L^2}
 + \sum_{\ell=1,2} \biggl\{ \underline{\rho}_\ell\underline{h}_\ell \biggl(
  \sum_{l=1}^n((\partial_t A_\ell)\partial_l\dot{\bm{\phi}}_\ell,\partial_l\dot{\bm{\phi}}_\ell)_{L^2}
   + (\underline{h}_\ell\delta)^{-2}((\partial_t C_\ell)\dot{\bm{\phi}}_\ell,\dot{\bm{\phi}}_\ell)_{L^2} \biggr) \\
 + 2\underline{\rho}_\ell([\partial_t, \theta_\ell\bm{l}_\ell^\mathrm{T}(\bm{v}\cdot\nabla)]\dot{\bm{\phi}}_\ell, \dot{\zeta})_{L^2}
 \biggr\}.
\end{align*}

Here, as in the proof of Lemma~\ref{L.A0-coercive} we have 
$\sqrt{\underline{\rho}_\ell/\underline{h}_\ell}\theta_\ell(|\bm{v}|+|\partial_t \bm{v}|) \lesssim 1$ for $\ell=1,2$. 
In view of the relations $\partial_t\theta_1=-\partial_t\theta_2=\theta_1\theta_2(H_1^{-1}\partial_t H_1 - H_2^{-1}\partial_t H_2)$, 
we have $|\partial_t\theta_\ell| \lesssim \theta_1\theta_2$ for $\ell=1,2$. 
Therefore, we obtain $|I_1| \lesssim \mathscr{E}(\dot{\bm{U}})$. 
As for $I_2$, by integration by parts we have 

\begin{align*}
I_2 &= ((\nabla\cdot(a\bm{u}))\dot{\zeta},\dot{\zeta})_{L^2} \\
&\quad\;
 -\sum_{\ell=1,2}\underline{\rho}_\ell\underline{h}_\ell \biggl\{ \sum_{l=1}^n \bigl\{
  2(A_\ell\partial_l\dot{\bm{\phi}}_\ell,((\partial_l\bm{u})\cdot\nabla)\dot{\bm{\phi}}_\ell)_{L^2}
  + (((\bm{u}\cdot\nabla)^*A_\ell)\partial_l\dot{\bm{\phi}}_\ell,\partial_\ell\dot{\bm{\phi}}_\ell)_{L^2} \bigr\} \\
&\makebox[7em]{}
 +(\underline{h}_\ell\delta)^{-2}(((\bm{u}\cdot\nabla)^*C_\ell)\dot{\bm{\phi}}_\ell,\dot{\bm{\phi}}_\ell)_{L^2} \biggr\} \\
&\quad\;
 +2\sum_{\ell=1,2}\underline{\rho}_\ell\bigl\{
  ((\nabla\cdot\bm{u})\dot{\zeta},\theta_\ell\bm{l}_\ell^\mathrm{T}(\bm{v}\cdot\nabla)\dot{\bm{\phi}}_\ell)_{L^2}
  + (\dot{\zeta}, [\bm{u}\cdot\nabla,\theta_\ell\bm{l}_\ell^\mathrm{T}(\bm{v}\cdot\nabla)]\dot{\bm{\phi}}_\ell)_{L^2}.
\end{align*}

By using~\eqref{parameters}, we see that 

\[
\theta_1 \simeq \frac{\underline{\rho}_2\underline{h}_1}{\underline{\rho}_1\underline{h}_2 + \underline{\rho}_2\underline{h}_1}
 = \frac{\underline{\rho}_2}{\underline{h}_2}, \qquad
\theta_2 \simeq \frac{\underline{\rho}_1\underline{h}_2}{\underline{\rho}_1\underline{h}_2 + \underline{\rho}_2\underline{h}_1}
 = \frac{\underline{\rho}_1}{\underline{h}_1}.
\]

Therefore, we have $|\bm{u}| \leq \theta_2|\bm{u}_1|+\theta_1|\bm{u}_2| \lesssim 1$. 
In view of $|\nabla\theta_\ell| \lesssim \theta_1\theta_2$ for $\ell=1,2$, we have also $|\nabla\bm{u}| \lesssim 1$ and 
$\sqrt{\rho_\ell/\underline{h}_\ell}\theta_l|\nabla\bm{v}| \lesssim 1$ for $\ell=1,2$. 
Hence, we obtain $|I_2| \lesssim \mathscr{E}(\dot{\bm{U}})$. 
Finally, as for $I_3$, we have 

\begin{align*}
I_3 &= 2(\partial_t\dot{\zeta},\dot{f}_0)_{L^2} -2 (\dot{\zeta},\nabla\cdot(\bm{u}\dot{f}_0))_{L^2} \\
&\quad\;
 +2\sum_{\ell=1,2}\underline{\rho}_\ell((\partial_t+\bm{u}\cdot\nabla)\dot{\bm{\phi}}_\ell,
  \dot{\bm{f}}_\ell - (\nabla\cdot(\theta_\ell\bm{l}_\ell\otimes\bm{v}))\dot{\zeta})_{L^2} \\
&\lesssim \|\dot{f}_0\|_{H^1}( \|\partial_t\dot{\zeta}\|_{H^{-1}}+\|\dot{\zeta}\|_{L^2} )
 + \sum_{\ell=1,2}\underline{\rho}_\ell( \|\dot{\bm{f}}_\ell\|_{L^2} + \|\dot{\zeta}\|_{L^2})
  \|(\partial_t\dot{\bm{\phi}}_\ell,\nabla\dot{\bm{\phi}}_\ell)\|_{L^2}.
\end{align*}

Summarizing the above estimates we obtain 

\begin{align*}
\frac{\mathrm{d}}{\mathrm{d}t}(\mathscr{A}_0^\mathrm{mod}\dot{\bm{U}},\dot{\bm{U}})_{L^2}
&\lesssim \mathscr{E}(\dot{\bm{U}}) + 
 \|\dot{f}_0\|_{H^1}( \|\partial_t\dot{\zeta}\|_{H^{-1}}+\|\dot{\zeta}\|_{L^2} ) \\
&\quad\;
 + \sum_{\ell=1,2}\underline{\rho}_\ell( \|\dot{\bm{f}}_\ell\|_{L^2} + \|\dot{\zeta}\|_{L^2})
  \|(\partial_t\dot{\bm{\phi}}_\ell,\nabla\dot{\bm{\phi}}_\ell)\|_{L^2}.
\end{align*}

This together with Lemma~\ref{L.A0-coercive} and Gronwall's inequality gives the desired estimate.

\label{L.EE-low}
Let $c,M$ be positive constants and $m$ an integer such that $m>\frac{n}{2}+1$. 
There exists a positive constant $C$ such that for any  positive parameters $\underline{h}_1, \underline{h}_2, \delta$ 
satisfying $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, if $\zeta\in H^{m-1}$, $b\in W^{m,\infty}$, 
$H_1=1-\underline{h}_1^{-1}\zeta$, and $H_2=1+\underline{h}_2^{-1}\zeta-\underline{h}_2^{-1}b$ satisfy 

\[
\begin{cases}
 \underline{h}_1^{-1}\|\zeta\|_{H^{m-1}} + \underline{h}_2^{-1}\|\zeta\|_{H^{m-1}}
  + \underline{h}_2^{-1}\|b\|_{W^{m,\infty}} \leq M, \\
 H_1(\bm{x})\geq c, \quad H_2(\bm{x})\geq c \quad\mbox{for}\quad \bm{x}\in\mathbf{R}^n,
\end{cases}
\]

and if $\bm{\varphi}_1$ and $\bm{\varphi}_2$ satisfy 

\[
\begin{cases}
