  - \Lambda_1(\zeta,\delta,\underline{h}_1)\phi_1)\|_{H^k}
  \leq C \underline{h}_1(\underline{h}_1\delta)^{2j}\|\nabla \phi_1\|_{H^{k+2j+1}}, \\
 \|(-\Delta)^{-\frac12}(\underline{h}_2\Lambda_2^{(N)}(\zeta,b,\delta,\underline{h}_2)\phi_2
  - \Lambda_2(\zeta,b,\delta,\underline{h}_2)\phi_2)\|_{H^k}
  \leq C \underline{h}_2(\underline{h}_2\delta)^{2j}\|\nabla \phi_2\|_{H^{k+2j+1}}.
\end{cases}
\]

\label{L.estimate-DN2}
Let $c, M$ be positive constants and $m$ an integer such that $m>\frac{n}{2}+2$. 
There exists a positive constant $C$ such that for any positive parameters 
$\underline{h}_1, \underline{h}_2, \delta$ satisfying $\underline{h}_1\delta, \underline{h}_2\delta \leq 1$, 
if $\zeta\in H^m$, $b\in W^{m,\infty}$, $H_1 = 1 - \underline{h}_1^{-1}\zeta$, 
and $H_2 = 1 + \underline{h}_2^{-1}\zeta - \underline{h}_2^{-1}b$ satisfy~\eqref{eq-Hyp20}, 
then for any $\phi_1,\phi_2 \in \mathring{H}^{k+1}$ with $|k|\leq m-1$ we have 

\[
\begin{cases}
 \|\Lambda_1(\zeta,\delta,\underline{h}_1)\phi_1\|_{H^{k-1}} \leq C\underline{h}_1\|\nabla\phi_1\|_{H^k}, \\
 \|\Lambda_2(\zeta,b,\delta,\underline{h}_2)\phi_2\|_{H^{k-1}} \leq C\underline{h}_2\|\nabla\phi_2\|_{H^k}. 
\end{cases} 
\]

Let $\bm{\phi}_1$ and $\bm{\phi}_2$ be the unique solutions to~\eqref{Conditionsbis}, and 
$(\tilde{\bm{\mathfrak{r}}}_1,\tilde{\bm{\mathfrak{r}}}_2,\tilde{\mathfrak{r}}_0)$ the errors in 
Theorem~\ref{theorem-consistency2}. 
Then, the errors $(\bm{\mathfrak{r}}_1,\bm{\mathfrak{r}}_2,\mathfrak{r}_0)$ in the proposition can be written as 

\[
\begin{cases}
 \bm{\mathfrak{r}}_1 = \tilde{\bm{\mathfrak{r}}}_1 - L_1(H_1,\delta,\underline{h}_1)(\tilde{\bm{\phi}}_1-\bm{\phi}_1), \\
 \bm{\mathfrak{r}}_2 = \tilde{\bm{\mathfrak{r}}}_2 + L_2(H_2,b,\delta,\underline{h}_2)(\tilde{\bm{\phi}}_2-\bm{\phi}_2), \\
 \mathfrak{r}_0 = \tilde{\mathfrak{r}}_0 + \underline{\rho}_1\{
  \underline{h}_1^{-1}(\partial_t\zeta)(\tilde{w}_1-w_1)
   - \frac12\bigl( (\tilde{\bm{u}}_1+\bm{u}_1)\cdot(\tilde{\bm{u}}_1-\bm{u}_1)
    + (\underline{h}_1\delta)^{-2}(\tilde{w}_1+w_1)(\tilde{w}_1-w_1) \bigr)\} \\
 \qquad - \underline{\rho}_2\{
  \underline{h}_2^{-1}(\partial_t\zeta)(\tilde{w}_2-w_2)
   - \frac12\bigl( (\tilde{\bm{u}}_2+\bm{u}_2)\cdot(\tilde{\bm{u}}_2-\bm{u}_2)
    + (\underline{h}_2\delta)^{-2}(\tilde{w}_2+w_2)(\tilde{w}_2-w_2) \bigr)\}.
\end{cases}
\]

Therefore, we have 

\[
\|\bm{\mathfrak{r}}_\ell-\tilde{\bm{\mathfrak{r}}}_\ell\|_{H^k}
\lesssim \|\nabla(\tilde{\bm{\phi}}_\ell-\bm{\phi}_\ell)\|_{H^{k+1}} + \|\tilde{\bm{\phi}}_\ell'-\bm{\phi}_\ell'\|_{H^{k+1}}
 + (\underline{h}_\ell\delta)^{-2}\|\tilde{\bm{\phi}}_\ell'-\bm{\phi}_\ell'\|_{H^k}
\]

for $-m\leq k\leq m-1$ and $\ell=1,2$. 
Applying this estimate with $k=m-(4N+5)$ and the estimate in Lemma~\ref{L.estimate-phi-phi} with $k=m-4(N+1)$ 
and using the result in Theorem~\ref{theorem-consistency2}, we obtain the first estimate in~\eqref{error-estimate2}. 
Since $m-2>\frac{n}{2}$, we have 

\begin{align*}
\|\mathfrak{r}_0-\tilde{\mathfrak{r}}_0\|_{H^k}
&\lesssim \sum_{\ell=1,2}\underline{\rho}_\ell\{ 
 (\|\tilde{\bm{u}}_\ell\|_{H^{m-2}}+\|\bm{u}_\ell\|_{H^{m-2}}) \|\tilde{\bm{u}}_\ell-\bm{u}_\ell\|_{H^k} \\
&\quad\;
 + \bigl(\underline{h}_\ell^{-1}\|\partial_t\zeta\|_{H^{m-2}} + 
  (\underline{h}_\ell\delta)^{-2}(\|\tilde{w}_\ell\|_{H^{m-2}}+\|w_\ell\|_{H^{m-2}}) \bigr)\|\tilde{w}_\ell-w_\ell\|_{H^k} \}
\end{align*}

for $|k|\leq m-2$.
Here, it follows from Lemmas~\ref{L.Lambda},~\ref{L.elliptic}, and~\ref{L.estimate-phi-phi} that 

\begin{align*}
\sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell
 (\|\bm{u}_\ell\|_{H^{m-1}}^2 + (\underline{h}_\ell\delta)^{-2}\|w_\ell\|_{H^{m-1}}^2 )
&\lesssim \sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell
 (\|\nabla\bm{\phi}_\ell\|_{H^{m-1}}^2 + (\underline{h}_\ell\delta)^{-2}\|\bm{\phi}_\ell'\|_{H^{m-1}}^2) \\
&\lesssim \sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell \|\nabla\phi_\ell\|_{H^{m-1}}^2,
\end{align*}

\begin{align*}
\sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell
 (\|\tilde{\bm{u}}_\ell\|_{H^{m-1}}^2 + (\underline{h}_\ell\delta)^{-2}\|\tilde{w}_\ell\|_{H^{m-1}}^2 )
&\lesssim \sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell
 (\|\nabla\tilde{\bm{\phi}}_\ell\|_{H^{m-1}}^2 + (\underline{h}_\ell\delta)^{-2}\|\tilde{\bm{\phi}}_\ell'\|_{H^{m-1}}^2) \\
&\lesssim \min\biggl\{\frac{\underline{h}_1}{\underline{\rho}_1},\frac{\underline{h}_2}{\underline{\rho}_2} \biggr\}
  \|\nabla(\underline{\rho}_2\phi_2-\underline{\rho}_1\phi_1)\|_{H^{m-1}}^2 \\
&\lesssim \sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell \|\nabla\phi_\ell\|_{H^{m-1}}^2,
\end{align*}

and

\begin{align*}
&\sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell
 (\|\tilde{\bm{u}}_\ell-\bm{u}_\ell\|_{H^k}^2 + (\underline{h}_\ell\delta)^{-2}\|\tilde{w}_\ell-w_\ell\|_{H^k}^2 ) \\
&\makebox[5em]{}
\lesssim \sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell
 (\|\nabla(\tilde{\bm{\phi}}_\ell-\bm{\phi}_\ell)\|_{H^k}^2
  + (\underline{h}_\ell\delta)^{-2}\|\tilde{\bm{\phi}}_\ell'-\bm{\phi}_\ell'\|_{H^k}^2) \\
&\makebox[5em]{}
\lesssim \sum_{\ell=1,2} \underline{\rho}_\ell \underline{h}_\ell (\underline{h}_\ell\delta)^{2(4N+2)}\|\nabla\phi_\ell\|_{H^{k+4N+3}}^2
\end{align*}

for $0\leq k\leq m-4(N+1)$. 
Moreover, it follows from Lemma~\ref{L.estimate-DN2} that 
$\|\partial_t\zeta\|_{H^{m-2}} = \|\Lambda_\ell\phi_\ell\|_{H^{m-2}}
