  + \underline{h}_1 L_1^{\mbox{\rm\tiny K},\mathrm{pr}}\partial^\beta\bm{\phi}_1^\mathrm{res} = \bm{f}_{1,\beta}^\mathrm{res}, \\
 \displaystyle
 {\bm l}_2^{\mbox{\rm\tiny K}}(\partial_t+\bm{u}_2^{\mbox{\rm\tiny K}}\cdot\nabla)\partial^\beta\zeta^\mathrm{res}
  - \underline{h}_2 L_2^{\mbox{\rm\tiny K},\mathrm{pr}}\partial^\beta\bm{\phi}_2^\mathrm{res} = \bm{f}_{2,\beta}^\mathrm{res}, \\
 \underline{\rho}_1{\bm l}_1^{\mbox{\rm\tiny K}}\cdot
  ( \partial_t+\bm{u}_1^{\mbox{\rm\tiny K}}\cdot\nabla )\partial^\beta\bm{\phi}_1^\mathrm{res} 
  - \underline{\rho}_2{\bm l}_2^{\mbox{\rm\tiny K}}\cdot
  ( \partial_t+\bm{u}_1^{\mbox{\rm\tiny K}}\cdot\nabla )\partial^\beta\bm{\phi}_2^\mathrm{res} 
  - a^{\mbox{\rm\tiny K}}\partial^\beta\zeta^\mathrm{res} = f_{0,\beta}^\mathrm{res},
\end{cases}
\]

\[
\begin{cases}
 \bm{f}_{1,\beta}^\mathrm{res} := \bm{f}_{1,\beta}^{\mbox{\rm\tiny K}} - \tilde{\bm{f}}_{1,\beta}^{\mbox{\rm\tiny IW}}
  - \underline{h}_1\partial^\beta\bm{\mathfrak{r}}_1
  + \underline{h}_1( L_1^{\mbox{\rm\tiny IW},\mathrm{pr}} - L_1^{\mbox{\rm\tiny K},\mathrm{pr}} )
   \partial^\beta\tilde{\bm{\phi}}_1^{\mbox{\rm\tiny IW}} \\
 \qquad\quad{}
  +\bigl(\bm{l}_1^{\mbox{\rm\tiny IW}}(\partial_t+\tilde{\bm{u}}_1^{\mbox{\rm\tiny IW}}\cdot\nabla)
   - \bm{l}_1^{\mbox{\rm\tiny K}}(\partial_t+\bm{u}_1^{\mbox{\rm\tiny K}}\cdot\nabla) \bigr)
   \partial^\beta\zeta^{\mbox{\rm\tiny IW}}, \\
 \bm{f}_{2,\beta}^\mathrm{res} := \bm{f}_{2,\beta}^{\mbox{\rm\tiny K}} - \tilde{\bm{f}}_{2,\beta}^{\mbox{\rm\tiny IW}}
  - \underline{h}_2\partial^\beta\bm{\mathfrak{r}}_2
  - \underline{h}_2( L_2^{\mbox{\rm\tiny IW},\mathrm{pr}} - L_2^{\mbox{\rm\tiny K},\mathrm{pr}} )
   \partial^\beta\tilde{\bm{\phi}}_2^{\mbox{\rm\tiny IW}} \\
 \qquad\quad{}
  +\bigl(\bm{l}_2^{\mbox{\rm\tiny IW}}(\partial_t+\tilde{\bm{u}}_2^{\mbox{\rm\tiny IW}}\cdot\nabla)
   - \bm{l}_2^{\mbox{\rm\tiny K}}(\partial_t+\bm{u}_2^{\mbox{\rm\tiny K}}\cdot\nabla) \bigr)
   \partial^\beta\zeta^{\mbox{\rm\tiny IW}}, \\
 f_{0,\beta}^\mathrm{res} := f_{0,\beta}^{\mbox{\rm\tiny K}} - \tilde{f}_{0,\beta}^{\mbox{\rm\tiny IW}}
  - \partial^\beta \mathfrak{r}_0 - (\tilde{a}^{\mbox{\rm\tiny IW}}
  - a^{\mbox{\rm\tiny K}})\partial^\beta \zeta^{\mbox{\rm\tiny IW}} \\
 \qquad\quad{}
 + \underline{\rho}_1\bigl( {\bm l}_1^{\mbox{\rm\tiny IW}} ( \partial_t+\tilde{\bm{u}}_1^{\mbox{\rm\tiny IW}}\cdot\nabla )
  - {\bm l}_1^{\mbox{\rm\tiny K}} ( \partial_t+\bm{u}_1^{\mbox{\rm\tiny K}}\cdot\nabla ) \bigr)\cdot
  \partial^\beta \tilde{\bm{\phi}}_1^{\mbox{\rm\tiny IW}} \\
 \qquad\quad{}
 - \underline{\rho}_2\bigl( {\bm l}_2^{\mbox{\rm\tiny IW}} ( \partial_t+\tilde{\bm{u}}_2^{\mbox{\rm\tiny IW}}\cdot\nabla )
  - {\bm l}_2^{\mbox{\rm\tiny K}} ( \partial_t+\bm{u}_2^{\mbox{\rm\tiny K}}\cdot\nabla ) \bigr)\cdot
  \partial^\beta \tilde{\bm{\phi}}_2^{\mbox{\rm\tiny IW}}.
\end{cases}
\]

As we saw, all the assumptions in Proposition~\ref{L.energy-estimate} are satisfied, so that 
we have 

\[
\mathscr{E}(\partial^\beta \bm{U}^\mathrm{res}(t)) \lesssim 
 \int_0^t\mathscr{F}_\beta^\mathrm{res}(\tau)\mathrm{d}\tau,
\]

where $\bm{U}^\mathrm{res}:=(\zeta^\mathrm{res},\bm{\phi}_1^\mathrm{res},\bm{\phi}_2^\mathrm{res})^\mathrm{T}$, 
$\mathscr{E}$ is defined in~\eqref{def-E}, and 

\begin{align*}
\mathscr{F}_\beta^\mathrm{res}
&=  \|f_{0,\beta}^\mathrm{res}\|_{H^1}( \|\partial_t \zeta^\mathrm{res}\|_{H^{k-1}}
 + \|\zeta^\mathrm{res}\|_{H^k} ) \\
&\quad\;
 + \sum_{\ell=1,2}\underline{\rho}_\ell( \|\bm{f}_{\ell,\beta}^\mathrm{res}\|_{L^2} + \|\zeta^\mathrm{res}\|_{H^k} )
  ( \|\nabla\partial_t \bm{\phi}_\ell^\mathrm{res}\|_{H^{k-1}} + \|\nabla \bm{\phi}_\ell^\mathrm{res}\|_{H^k} ).
\end{align*}

\begin{align*}
\|\bm{f}_{\ell,\beta}^\mathrm{res}\|_{L^2}
&\lesssim
 (\|\partial_t\zeta^{\mbox{\rm\tiny IW}}\|_{H^{m-1}}+\|\tilde{\bm{u}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m})
  \|\zeta^\mathrm{res}\|_{H^k} \\
&\quad\;
 + \underline{h}_\ell(\|\nabla\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m}
  + \|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^m}
  + (\underline{h}_\ell\delta)^{-2}\|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^{m-1}})
  \|\zeta^\mathrm{res}\|_{H^k} \\
&\quad\;
  + \underline{h}_\ell(\|\nabla\tilde{\bm{\phi}}_\ell^\mathrm{res}\|_{H^k}
  + \|\tilde{\bm{\phi}}_\ell^{\mathrm{res} \, \prime}\|_{H^k}
  + (\underline{h}_\ell\delta)^{-2}\|\tilde{\bm{\phi}}_\ell^{\mathrm{res} \, \prime}\|_{H^{k-1}}) \\
&\quad\;
 + \|\partial_t\zeta^\mathrm{res}\|_{H^{k-1}}
 + \|\tilde{\bm{u}}_\ell^{\mbox{\rm\tiny IW}}-\bm{u}_\ell^{\mbox{\rm\tiny K}}\|_{H^k}
 + \underline{h}_\ell\|\bm{\mathfrak{r}}_\ell\|_{H^k}
\end{align*}

\begin{align*}
& \bigl\{ 
 \bigl( [\partial^\beta, \bm{l}_2^{\mbox{\rm\tiny K}}]
  - \bm{l}_2'(H_2^{\mbox{\rm\tiny K}})(\underline{h}_2^{-1}\partial^\beta\zeta^{\mbox{\rm\tiny K}}) \bigr) 
 - \bigl( [\partial^\beta, \bm{l}_2^{\mbox{\rm\tiny IW}}]
  - \bm{l}_2'(H_2^{\mbox{\rm\tiny IW}})(\underline{h}_2^{-1}\partial^\beta\zeta^{\mbox{\rm\tiny IW}}) \bigr) \bigr\}^\mathrm{T}
  \partial_t\tilde{\bm{\phi}}_2^{\mbox{\rm\tiny IW}} \\
&\makebox[1em]{}= \int_0^1
 \bigl\{ [\partial^\beta, \bm{l}_2'(sH^{\mbox{\rm\tiny IW}}+(1-s)H^{\mbox{\rm\tiny K}})] \\
&\makebox[4.5em]{}
  - \bm{l}_2''(sH^{\mbox{\rm\tiny IW}}+(1-s)H^{\mbox{\rm\tiny K}})
   \underline{h}_2^{-1}\partial^\beta( s\zeta^{\mbox{\rm\tiny IW}}+(1-s)\zeta^{\mbox{\rm\tiny K}} )
   \bigr\}^\mathrm{T}(\underline{h}_2^{-1}\zeta^\mathrm{res})\partial_t\tilde{\bm{\phi}}_2^{\mbox{\rm\tiny IW}} \\
&\makebox[1em]{}\phantom{= \int_0^1}
 + \bm{l}_2'(sH^{\mbox{\rm\tiny IW}}+(1-s)H^{\mbox{\rm\tiny K}})
  \bigl\{ [\partial^\beta,\underline{h}_2^{-1}\zeta^\mathrm{res}]
   - (\partial^\beta(\underline{h}_2^{-1}\zeta^\mathrm{res})) \bigr\}^\mathrm{T}\partial_t\tilde{\bm{\phi}}_2^{\mbox{\rm\tiny IW}}
  \mathrm{d}s.
\end{align*}

\begin{align*}
\|f_{0,\beta}^\mathrm{res}\|_{H^1}
&\lesssim \sum_{l=1,2}\underline{\rho}_\ell\bigl\{
 (\|\nabla\partial_t\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^{m-2}}
  + \|\partial_t\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^{m-2}})\|\zeta^\mathrm{res}\|_{H^k} \\
&\quad\;
  + (\|\tilde{\bm{u}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m}+\|\bm{u}_\ell^{\mbox{\rm\tiny K}}\|_{H^m})
   (\|\nabla\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m}
  + \|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^m})\|\zeta^\mathrm{res}\|_{H^k} \\
&\quad\;
 + (\underline{h}_\ell\delta)^{-2}\|w_\ell^{\mbox{\rm\tiny K}}\|_{H^m}
  \|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^m}\|\zeta^\mathrm{res}\|_{H^k} 
 + \|\nabla\partial_t\tilde{\bm{\phi}}_\ell^\mathrm{res}\|_{H^{k-1}}
  + \|\partial_t\tilde{\bm{\phi}}_\ell^{\mathrm{res} \, \prime}\|_{H^{k-1}} \\
&\quad\;
 + \|\bm{u}_\ell^{\mbox{\rm\tiny K}}\|_{H^m} (\|\nabla\tilde{\bm{\phi}}_\ell^\mathrm{res}\|_{H^k}
  + \|\tilde{\bm{\phi}}_\ell^{\mathrm{res} \, \prime}\|_{H^k} )
 + (\underline{h}_\ell\delta)^{-2}\|w_\ell^{\mbox{\rm\tiny K}}\|_{H^m}
  \|\tilde{\bm{\phi}}_\ell^{\mathrm{res} \, \prime}\|_{H^k} \\
&\quad\;
 + (\|\bm{u}_\ell^{\mbox{\rm\tiny K}}\|_{H^m} + \|\tilde{\bm{u}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m}
  + \|\nabla\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m}
  + \|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^m} )
   \|\tilde{\bm{u}}_\ell^{\mbox{\rm\tiny IW}}-\bm{u}_\ell^{\mbox{\rm\tiny K}}\|_{H^k} \\
&\quad\;
 + (\underline{h}_\ell\delta)^{-2}( \|w_\ell^{\mbox{\rm\tiny K}}\|_{H^m}
  + \|\tilde{w}_\ell^{\mbox{\rm\tiny IW}}\|_{H^m} + \|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^m} )
  \|\tilde{w}_\ell^{\mbox{\rm\tiny IW}}-w_\ell^{\mbox{\rm\tiny K}}\|_{H^k} \bigr\} 
 + \|\mathfrak{r}_0\|_{H^{k+1}}
\end{align*}

\begin{align*}
\|\nabla\phi_\ell^{\mbox{\rm\tiny K}}-\nabla\phi_\ell^{\mbox{\rm\tiny IW}}\|_{H^k}
&\lesssim \|\nabla\bm{\phi}_\ell^\mathrm{res}\|_{H^k}+\|\bm{\phi}_\ell^{\mathrm{res} \, \prime}\|_{H^k}
 + \underline{h}_\ell^{-1}\|\zeta^\mathrm{res}\|_{H^{k+1}}\|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^m} \\
&\quad\;
 + \|\nabla(\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW}}-\bm{\phi}_\ell^{\mbox{\rm\tiny IW}})\|_{H^k}
 + \|\tilde{\bm{\phi}}_\ell^{\mbox{\rm\tiny IW} \, \prime}-\bm{\phi}_\ell^{\mbox{\rm\tiny IW} \, \prime}\|_{H^k}. 
\end{align*}

\begin{align*}
& \sum_{\ell=1,2}\underline{\rho}_\ell\int_{\Omega_{\ell,0}} \bigl(
 |I_\delta\nabla_X\Phi_\ell^\mathrm{res}|^2
 - I_\delta\nabla_X\Phi_\ell^\mathrm{res}\cdot(I-\mathcal{P}_\ell)I_\delta\nabla_X\tilde{\Phi}_\ell \bigr)\mathrm{d}X \\
&\quad= \sum_{\ell=1,2}\int_{\partial\Omega_{\ell,0}}
 \underline{\rho}_\ell\Phi_\ell^\mathrm{res}(N_\ell\cdot I_\delta\mathcal{P}_\ell I_\delta\nabla_X\tilde{\Phi}_\ell
  - N_\ell\cdot I_\delta^2\nabla_X\Psi_\ell) \mathrm{d}S \\
&\quad= \sum_{\ell=1,2}\int_{\mathbf{R}^n}
 \underline{\rho}_1\bigl[ \Phi_1^\mathrm{res}\{ (\bm{e}_z\cdot I_\delta\mathcal{P}_2 I_\delta\nabla_X\tilde{\Phi}_2
   - \bm{e}_z\cdot I_\delta^2\nabla_X\Psi_2) \\
&\makebox[7em]{}
  - (\bm{e}_z\cdot I_\delta\mathcal{P}_1 I_\delta\nabla_X\tilde{\Phi}_1
   - \bm{e}_z\cdot I_\delta^2\nabla_X\Psi_1) \} \bigr]\bigr|_{z=0} \mathrm{d}\bm{x} \\
&\quad=0,
\end{align*}

It is easy to see that 

\begin{align*}
\|I_\delta\nabla_X\Phi_1^\mathrm{res,1}\|_{L^2(\Omega_1)}^2
&\lesssim (\underline{h}_1\delta)^2\|R_1\|_{L^2(\Omega_1)}^2 \\
&\lesssim \underline{h}_1(\underline{h}_1\delta)^2\|(r_{1,0},r_{1,1},\ldots,r_{1,2N+2})\|_{L^2} \\
&\lesssim \underline{h}_1(\underline{h}_1\delta)^{2(4N+3)}\|\nabla\tilde{\bm{\phi}}_1\|_{H^{4N+3}}^2
\end{align*}

and that 

\begin{align*}
\|I_\delta\nabla_X\Phi_2^\mathrm{res,1}\|_{L^2(\Omega_2)}^2
&\lesssim \underline{h}_2(\underline{h}_2\delta)^2( \underline{h}_2^{-1}\|R_2\|_{L^2(\Omega_2)}^2 + \|r_B\|_{L^2}^2 ) \\
&\lesssim \underline{h}_2(\underline{h}_2\delta)^2( \|(r_{2,0},r_{2,1},\ldots,r_{2,2N^*+2})\|_{L^2} + \|r_B\|_{L^2}^2 ) \\
&\lesssim \underline{h}_2(\underline{h}_2\delta)^{2(4N+3)}
 ( \|\nabla\tilde{\bm{\phi}}_2\|_{H^{4N+3}}+\|\tilde{\bm{\phi}}_2'\|_{H^{4N+3}} ).
\end{align*}
